def _normalize_confidence(val):
    if isinstance(val, str):
        return val.upper() if val.upper() in ("HIGH", "MEDIUM", "LOW") else "MEDIUM"
    if isinstance(val, (int, float)):
        if val >= 0.8:
            return "HIGH"
        if val >= 0.5:
            return "MEDIUM"
        return "LOW"
    return "MEDIUM"


def _derive_stage_label(stage_key):
    return STAGE_LABELS.get(stage_key, stage_key.replace("_", " ").title())


def _derive_stage_abbrev(stage_key):
    if stage_key in STAGE_ABBREVS:
        return STAGE_ABBREVS[stage_key]
    parts = stage_key.split("_")
    if len(parts) == 1:
        return parts[0][:3].upper()
    return "".join(p[0].upper() for p in parts[:4])

