def _get_tool_icon(tool_name):
    key = tool_name.lower().strip()
    slug = TOOL_SIMPLE_ICON_SLUGS.get(key)
    if slug:
        return {"url": f"https://cdn.simpleicons.org/{slug}", "emoji": TOOL_EMOJI_FALLBACKS.get(key, DEFAULT_TOOL_EMOJI)}
    domain = TOOL_FAVICON_DOMAINS.get(key)
    if domain:
        return {"url": f"https://www.google.com/s2/favicons?domain={domain}&sz=64", "emoji": TOOL_EMOJI_FALLBACKS.get(key, DEFAULT_TOOL_EMOJI)}
    svg = TOOL_SVG_ICONS.get(key)
    if svg:
        return {"url": svg, "emoji": TOOL_EMOJI_FALLBACKS.get(key, DEFAULT_TOOL_EMOJI)}
    return {"url": None, "emoji": TOOL_EMOJI_FALLBACKS.get(key, DEFAULT_TOOL_EMOJI)}


def slugify(text):
    return re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")


def _lane_chip(l):
    if l.get("logo_url"):
        em = l.get("emoji", DEFAULT_TOOL_EMOJI)
        img = f'<img class="chip-logo" src="{l["logo_url"]}" alt="" onerror="this.outerHTML=\'<span class=chip-emoji>{em}</span>\'">'
    elif l.get("emoji"):
        img = f'<span class="chip-emoji">{l["emoji"]}</span>'
    else:
        img = ''
    return f'<span class="lane-chip {l["type"]}">{img}{_h(l["name"])}</span>'


def clean_title(description, max_words=10, max_chars=55, owner=None):
    title = description
    if owner:
        owner_parts = [p.strip() for p in owner.split(",")[0].split("+")[0].split("/")[0].split()]
        first_name = owner_parts[0].lower() if owner_parts else ""
        words = title.split()
        if words and words[0].lower() == first_name:
            words = words[1:]
            if words:
                words[0] = words[0].capitalize()
            title = " ".join(words)
    title = re.sub(r"^(PAIN|OPTIMISATION|DECISION|OPT|AUTO):\s*", "", title, flags=re.IGNORECASE)
    for sep in [". ", ": ", " — ", " - ", " (", "; "]:
        if sep in title:
            title = title.split(sep)[0]
            break
    words = title.split()
    if words and words[0].lower() in ("the", "a", "an", "all", "each", "every"):
        words = words[1:]
        if words:
            words[0] = words[0].capitalize()
    if len(words) > max_words:
        words = words[:max_words]
    while words and words[-1].rstrip(".,;:") in ("and", "or", "the", "a", "to", "for", "in", "of", "with", "from", "by", "on", "at", "as"):
        words = words[:-1]
    if words:
        words[-1] = words[-1].rstrip(".,;:(")
    result = " ".join(words)
    if len(result) > max_chars:
        truncated = result[:max_chars]
        last_space = truncated.rfind(" ")
        if last_space > max_chars // 2:
            result = truncated[:last_space]
    return result


def classify_tool(tool_name):
    lower = tool_name.lower().strip()
    if lower in SYSTEM_TOOLS or any(s in lower for s in ["crm", "portal", "app", "platform", "tracker", "sheets", "xero"]):
        return "system"
    if lower in EXTERNAL_ACTORS or any(s in lower for s in ["partner", "agency", "dealer", "customer", "prospect", "lender"]):
        return "external"
    return "offline"


def _is_tool_name(name):
    """Check if a lane name looks like a tool (for backward compat with tool-based lanes)."""
    lower = name.lower().strip()
    return lower in SYSTEM_TOOLS or lower in TOOL_SIMPLE_ICON_SLUGS or lower in TOOL_FAVICON_DOMAINS or lower in ("manual",)


def classify_lane(name):
    """Classify a lane name as role, external, system, or tool-based (backward compat)."""
    if _is_tool_name(name):
        return classify_tool(name)
    lower = name.lower().strip()
    if lower.startswith("external:") or lower in EXTERNAL_ACTORS:
        return "external"
    if lower in ("automated", "system"):
        return "system"
    return "role"


def sanitize_id(raw):
    return re.sub(r"[^A-Za-z0-9_]", "_", raw).strip("_")


def sanitize_lane_id(name):
    return "Lane_" + re.sub(r"[^A-Za-z0-9]", "_", name).strip("_")


def infer_task_type(step):
    """Legacy fallback: only called when step lacks task_type field."""
    return step.get("task_type", "user_task")


def get_initials(owner):
    if not owner:
        return "??"
    if "automated" in owner.lower():
        return "AU"
    words = owner.split()
    if len(words) >= 2:
        return (words[0][0] + words[1][0]).upper()
    return owner[:2].upper()


def _h(text):
    if not text:
        return ""
    return html_escape(str(text))


# ─── Splitting Logic ───────────────────────────────────────────────────────

_SUBPROCESS_THRESHOLD = 20  # stages with more steps than this get sub-process grouping
_SUBPROCESS_TARGET = 12     # ideal steps per group
_SUBPROCESS_HARD_LIMIT = 20  # hard-split if no boundary found before this


class SubProcessGrouper:
    """Chunks a stage's steps into named sub-process groups for BPMN drill-down.

    Priority order:
      1. flow_id field on steps (explicit grouping)
      2. parallel_tracks[] on the stage object
      3. Role-boundary sequential chunking (primary heuristic)
    """

    def group(self, stage, steps: list) -> list[dict]:
        """Return list of {"name": str, "slug": str, "steps": list}.

        stage may be a string (stage_id) or a dict with stage attributes.
        """
        # 1. flow_id
        flow_ids = {s.get("flow_id") for s in steps if s.get("flow_id")}
        if flow_ids:
            return self._by_flow_id(steps, flow_ids)

        # 2. parallel_tracks on the stage (only available when stage is a dict)
        stage_dict = stage if isinstance(stage, dict) else {}
        tracks = stage_dict.get("parallel_tracks") or []
        if tracks and isinstance(tracks[0], dict) and tracks[0].get("step_ids"):
            return self._by_parallel_tracks(steps, tracks)

        # 3. role-boundary chunking
        return self._by_role_boundary(stage, steps)

    # ── flow_id grouping ─────────────────────────────────────────────────────

    def _by_flow_id(self, steps: list, flow_ids: set) -> list[dict]:
        groups: dict[str, list] = {}
        ungrouped: list = []
        for s in steps:
            fid = s.get("flow_id")
            if fid:
                groups.setdefault(fid, []).append(s)
            else:
                ungrouped.append(s)
        result = []
        for fid, fsteps in groups.items():
            name = fid.replace("_", " ").title()
            result.append({"name": name, "steps": fsteps, "slug": slugify(fid)})
        if ungrouped:
            result.append({"name": "General", "steps": ungrouped, "slug": "general"})
        return result

    # ── parallel_tracks grouping ─────────────────────────────────────────────

    def _by_parallel_tracks(self, steps: list, tracks: list) -> list[dict]:
        step_map = {s.get("step_id", ""): s for s in steps}
        result = []
        assigned_ids: set = set()
        for track in tracks:
            label = track.get("label") or track.get("name") or "Track"
            ids = track.get("step_ids") or []
            track_steps = [step_map[i] for i in ids if i in step_map]
            if track_steps:
                assigned_ids.update(ids)
                result.append({"name": label, "steps": track_steps, "slug": slugify(label)})
        unassigned = [s for s in steps if s.get("step_id", "") not in assigned_ids]
        if unassigned:
            result.append({"name": "General", "steps": unassigned, "slug": "general"})
        return result

    # ── role-boundary chunking ───────────────────────────────────────────────

    def _by_role_boundary(self, stage: dict, steps: list) -> list[dict]:
        """Split at persistent lane transitions (new lane lasts 3+ steps)."""
        if not steps:
            return []

        boundaries = self._find_boundaries(steps)
        raw_groups = self._slice_at_boundaries(steps, boundaries)
        merged = self._merge_small_groups(raw_groups)
        named = self._name_groups(stage, merged)
        return named

    def _find_boundaries(self, steps: list) -> list[int]:
        """Return indices where a new sub-process should start."""
        boundaries: list[int] = [0]
        n = len(steps)
        i = 0
        while i < n:
            current_lane = steps[i].get("lane_id") or steps[i].get("performer", "")
            # Count how many consecutive steps share this lane
            j = i + 1
            while j < n and (steps[j].get("lane_id") or steps[j].get("performer", "")) == current_lane:
                j += 1
            run_length = j - i
            # Current group size so far
            current_group_start = boundaries[-1]
            current_group_size = i - current_group_start
            if current_group_size >= _SUBPROCESS_TARGET and run_length >= 3:
                # Persistent role transition — good split point
                if i not in boundaries:
                    boundaries.append(i)
            elif current_group_size >= _SUBPROCESS_HARD_LIMIT:
                # Hard cap — split regardless
                if i not in boundaries:
                    boundaries.append(i)
            i = j
        return sorted(set(boundaries))

    def _slice_at_boundaries(self, steps: list, boundaries: list[int]) -> list[list]:
        groups = []
        for idx, start in enumerate(boundaries):
            end = boundaries[idx + 1] if idx + 1 < len(boundaries) else len(steps)
            groups.append(steps[start:end])
        return [g for g in groups if g]

    def _merge_small_groups(self, groups: list[list]) -> list[list]:
        """Merge groups that are too small (<4 steps) into their neighbour."""
        if not groups:
            return groups
        merged = [groups[0]]
        for g in groups[1:]:
            if len(g) < 4 and len(merged) > 0:
                merged[-1] = merged[-1] + g
            else:
                merged.append(g)
        return merged

    def _name_groups(self, stage, groups: list[list]) -> list[dict]:
        # First pass: compute dominant lane name for each group
        dominant_names = []
        for grp in groups:
            lane_counts: dict[str, int] = {}
            for s in grp:
                lane = s.get("lane_id") or s.get("performer", "")
                if lane:
                    lane_counts[lane] = lane_counts.get(lane, 0) + 1
            if lane_counts:
                dominant = max(lane_counts, key=lambda k: lane_counts[k])
                dominant_names.append(dominant.replace("_", " ").title())
            else:
                dominant_names.append(None)

        # If all dominant names are unique, use them (existing behavior)
        use_lane_names = (
            all(n is not None for n in dominant_names)
            and len(set(dominant_names)) == len(dominant_names)
        )

        result = []
        used_slugs: set = set()
        for i, grp in enumerate(groups):
            if use_lane_names:
                name = dominant_names[i]
            else:
                name = self._derive_content_name(grp, dominant_names[i])

            raw_slug = slugify(name)
            slug = raw_slug
            counter = 2
            while slug in used_slugs:
                slug = f"{raw_slug}-{counter}"
                name_with_counter = f"{name} {counter}"
                counter += 1
            used_slugs.add(slug)
            result.append({"name": name, "steps": grp, "slug": slug})
        return result

    def _derive_content_name(self, grp: list, dominant_lane: "str | None") -> str:
        """Derive a descriptive name from step titles when lane names are ambiguous."""
        first_step = grp[0] if grp else {}
        title = first_step.get("title") or first_step.get("step_id") or "Process"

        # Strip a leading lane-name prefix from the title so we get the action, not the actor
        if dominant_lane:
            for prefix in [dominant_lane, dominant_lane.title()]:
                if title.startswith(prefix):
                    title = title[len(prefix):].lstrip(" -:,")
                    break

        title = title.strip()
        if not title:
            # Nothing left after stripping -- fall back to first-to-last
            first = grp[0].get("title", grp[0].get("step_id", "Start")) if grp else "Start"
            last = grp[-1].get("title", grp[-1].get("step_id", "End")) if grp else "End"
            return f"{first} to {last}"

        # Truncate to ~40 chars at word boundary
        if len(title) > 40:
            truncated = title[:40].rsplit(" ", 1)[0]
            title = truncated if len(truncated) >= 15 else title[:40]

        return title


def split_stage_into_subprocesses(proc: dict, steps: list, tools_lookup: dict) -> dict:
    """Return {"groups": list, "use_subprocess": bool}.

    If use_subprocess is True, the caller should generate a multi-plane BPMN
    with collapsed sub-processes.  If False, generate a flat single-plane BPMN
    (current behaviour).

    proc may be the full process dict (preferred, enables parallel_tracks grouping)
    or a stage-key string (legacy, falls back to role-boundary chunking).
    """
    stage_key = proc.get("stage", "") if isinstance(proc, dict) else str(proc)
    if len(steps) > _SUBPROCESS_THRESHOLD:
        grouper = SubProcessGrouper()
        groups = grouper.group(proc, steps)
        # Only use sub-process layout if we actually got multiple groups
        if len(groups) > 1:
            return {"groups": groups, "use_subprocess": True}

    # Flat — existing behaviour (single group, possibly split by flow_id)
    flow_ids = {s.get("flow_id") for s in steps if s.get("flow_id")}
    if flow_ids:
        groups = SubProcessGrouper()._by_flow_id(steps, flow_ids)
    else:
        groups = [{"name": _derive_stage_label(stage_key),
                   "steps": steps, "slug": slugify(stage_key or "stage")}]
    return {"groups": groups, "use_subprocess": False}


# ─── Stage lifecycle ordering ─────────────────────────────────────────────

_STAGE_LIFECYCLE_ORDER = {
    "acquisition": 0, "sales": 1, "marketing": 2, "lead": 3, "tender": 5, "bidding": 6,
    "estimating": 20, "quoting": 21, "materials_takeoffs": 22, "procurement": 23,
    "design": 24, "engineering": 25,
    "onboarding": 40, "project_setup": 41, "recruitment": 42, "hiring": 43,
    "fulfilment": 60, "production": 61, "manufacturing": 62, "construction": 63,
    "installation": 64, "scheduling": 65, "operations": 66, "logistics": 67,
    "qa": 80, "qc": 81, "quality": 82, "health_safety": 83, "compliance": 84,
    "document_control": 85, "safety": 86,
    "timesheets": 90, "payroll": 91, "invoicing": 92, "finance": 93,
    "accounting": 94, "billing": 95, "administration": 96, "hr": 97,
    "retention": 100, "support": 101, "maintenance": 102, "equipment_tracking": 103,
    "it_support": 104, "change_management": 105, "product_development": 106,
}


def _stage_sort_key(stage_slug, original_index):
    if stage_slug in _STAGE_LIFECYCLE_ORDER:
        return (_STAGE_LIFECYCLE_ORDER[stage_slug], original_index)
    for key in sorted(_STAGE_LIFECYCLE_ORDER, key=len, reverse=True):
        if stage_slug.startswith(key):
            return (_STAGE_LIFECYCLE_ORDER[key], original_index)
    return (999, original_index)


# ─── Transformer ───────────────────────────────────────────────────────────

class BpmnTransformer:
    def __init__(self, extraction, tools_lookup, sessions):
        self.extraction = extraction
        self.tools_lookup = tools_lookup
        self.sessions = sessions

    def transform_all(self):
        all_processes = self.extraction.get("processes", [])
        global_step_to_stage = {}
        for proc in all_processes:
            stage_label = _derive_stage_label(proc["stage"])
            for s in proc.get("steps", []):
                sid = s.get("step_id", "")
                if sid:
                    global_step_to_stage[sid] = stage_label

        stages = []
        for idx, proc in enumerate(all_processes):
            stage = proc["stage"]
            all_flows = proc.get("sequence_flows") or []
            split_result = split_stage_into_subprocesses(
                proc, proc.get("steps", []), self.tools_lookup
            )
            groups = split_result["groups"]
            use_subprocess = split_result["use_subprocess"]
            stage_data = {
                "stage": stage, "label": _derive_stage_label(stage),
                "processes": [], "use_subprocess": use_subprocess, "_orig_idx": idx,
            }
            abbrev = _derive_stage_abbrev(stage)
            for sp in groups:
                sp_step_ids = {s.get("step_id") for s in sp["steps"]}
                intra_flows = []
                cross_flows = []
                for f in all_flows:
                    f_from = f.get("from", "")
                    f_to = f.get("to", "")
                    if f_from in sp_step_ids and f_to in sp_step_ids:
                        intra_flows.append(f)
                    elif f_from in sp_step_ids or f_to in sp_step_ids:
                        cf = dict(f)
                        if f_from in sp_step_ids and f_to not in sp_step_ids:
                            cf["_target_stage"] = global_step_to_stage.get(f_to, "another process")
                        elif f_to in sp_step_ids and f_from not in sp_step_ids:
                            cf["_source_stage"] = global_step_to_stage.get(f_from, "another process")
                        cross_flows.append(cf)
                sp["sequence_flows"] = intra_flows
                if cross_flows:
                    sp["_cross_flows"] = cross_flows
                    print(f"  INFO [{stage}]: {len(cross_flows)} cross-process flow(s): "
                          f"{[f.get('id', '?') for f in cross_flows]}", file=sys.stderr)
                process_id = f"{abbrev}-{sp['slug']}"
                transformed = self._transform_subprocess(sp, stage, process_id)
                stage_data["processes"].append(transformed)
            stages.append(stage_data)
        stages.sort(key=lambda s: _stage_sort_key(s["stage"], s.pop("_orig_idx")))
        return {"stages": stages}

    _START_TYPES = {"start_event", "start"}
    _END_TYPES = {"end_event", "end"}

    def _transform_subprocess(self, sp, stage, process_id):
        raw_steps = sp["steps"]
        lanes = self._build_lanes(raw_steps)

        fallback_lane = lanes[0]["id"] if lanes else "Lane_Manual"
        owner_counts = {}
        for s in raw_steps:
            o = s.get("owner") or ""
            if o and "automated" not in o.lower():
                owner_counts[o] = owner_counts.get(o, 0) + 1
        primary_event_lane = fallback_lane
        if owner_counts:
            primary_owner_name = max(owner_counts, key=owner_counts.get)
            primary_lid = sanitize_lane_id(primary_owner_name)
            for lane in lanes:
                if lane["id"] == primary_lid:
                    primary_event_lane = primary_lid
                    break
            else:
                if raw_steps:
                    first_step_lid = sanitize_lane_id(raw_steps[0].get("lane_id") or "Manual")
                    for lane in lanes:
                        if lane["id"] == first_step_lid:
                            primary_event_lane = first_step_lid
                            break

        lane_ids_in_use = {l["id"] for l in lanes}
        if primary_event_lane not in lane_ids_in_use and lane_ids_in_use:
            print(f"  WARN [{process_id}]: primary_event_lane '{primary_event_lane}' not in lanes, "
                  f"using fallback '{fallback_lane}'", file=sys.stderr)
            primary_event_lane = fallback_lane

        has_explicit_start = any(
            (s.get("element_type") or s.get("type", "")) in self._START_TYPES for s in raw_steps
        )
        has_explicit_end = any(
            (s.get("element_type") or s.get("type", "")) in self._END_TYPES for s in raw_steps
        )

        bpmn_steps = []
        start_id = f"Start_{process_id.replace('-','_')}"
        end_id = f"End_{process_id.replace('-','_')}"
        event_label = sp['name'][:25] if len(sp['name']) > 25 else sp['name']
        if not has_explicit_start:
            bpmn_steps.append({"bpmn_id": start_id, "step_id": "000", "title": f"{event_label} begins", "type": "start", "lane_id": primary_event_lane})

        step_id_to_bpmn_id = {}
        pid_safe = process_id.replace('-', '_')

        for step in raw_steps:
            raw_desc = step.get("description") or ""
            title = clean_title(raw_desc, owner=step.get("owner"))
            owner = step.get("owner") or "Unknown"
            element_type = step.get("element_type") or step.get("type", "task")
            annotations = step.get("annotations") or []

            mrs = self._build_meeting_refs(step)
            tool_names = [self.tools_lookup.get(tid, tid) for tid in (step.get("tool_ids") or step.get("tools_used") or [])]
            base_detail = {"_full_description": raw_desc, "owner": owner, "tool_names": tool_names}
            if step.get("duration_minutes"):
                base_detail["duration_per_instance_minutes"] = step["duration_minutes"]
            if step.get("frequency") and step.get("duration_minutes"):
                freq = step["frequency"]
                dur = step["duration_minutes"]
                if isinstance(freq, (int, float)) and freq > 0:
                    base_detail["time_estimate_hours_per_week"] = round((dur * freq) / 60, 1)
            if mrs:
                base_detail["meeting_references"] = mrs

            safe_step_id = sanitize_id(step.get("step_id", ""))
            bpmn_id = f"Task_{pid_safe}_{safe_step_id}"
            step_id_to_bpmn_id[step.get("step_id", "")] = bpmn_id

            lane_id = sanitize_lane_id(step.get("lane_id") or "Manual")

            bpmn_step = {
                "bpmn_id": bpmn_id,
                "step_id": step["step_id"], "title": title,
                "type": element_type, "lane_id": lane_id,
                "annotations": annotations,
                **base_detail,
            }
            if element_type == "task":
                bpmn_step["task_type"] = step.get("task_type", "user_task")
            bpmn_steps.append(bpmn_step)

        if has_explicit_start:
            for s in raw_steps:
                et = s.get("element_type") or s.get("type", "")
                if et in self._START_TYPES:
                    start_id = step_id_to_bpmn_id[s["step_id"]]
                    break
        if not has_explicit_end:
            bpmn_steps.append({"bpmn_id": end_id, "step_id": "END", "title": f"{event_label} complete", "type": "end", "lane_id": primary_event_lane})
        else:
            for s in raw_steps:
                et = s.get("element_type") or s.get("type", "")
                if et in self._END_TYPES:
                    end_id = step_id_to_bpmn_id[s["step_id"]]
                    break

        raw_flows = sp.get("sequence_flows") or []
        cross_flows = sp.get("_cross_flows") or []
        sequence_flows = []
        fc = 0

        explicit_pairs = set()
        has_outgoing = set()
        has_incoming = set()
        for rf in raw_flows:
            src = step_id_to_bpmn_id.get(rf.get("from", ""))
            tgt = step_id_to_bpmn_id.get(rf.get("to", ""))
            if src and tgt:
                fc += 1
                flow = {"id": f"Flow_{fc:02d}", "source_ref": src, "target_ref": tgt,
                        "_source_flow_id": rf.get("id", "")}
                if rf.get("condition"):
                    flow["condition_label"] = rf["condition"]
                sequence_flows.append(flow)
                explicit_pairs.add((src, tgt))
                has_outgoing.add(src)
                has_incoming.add(tgt)

        for cf in cross_flows:
            src_bid = step_id_to_bpmn_id.get(cf.get("from", ""))
            tgt_bid = step_id_to_bpmn_id.get(cf.get("to", ""))
            target_stage = cf.get("_target_stage", "another process")
            source_stage = cf.get("_source_stage", "another process")
            if src_bid and not tgt_bid:
                for bs in bpmn_steps:
                    if bs["bpmn_id"] == src_bid:
                        bs["title"] = f"{bs['title']} → {target_stage}"
                        break
                has_outgoing.add(src_bid)
            elif tgt_bid and not src_bid:
                for bs in bpmn_steps:
                    if bs["bpmn_id"] == tgt_bid:
                        bs["title"] = f"{source_stage} → {bs['title']}"
                        break
                has_incoming.add(tgt_bid)

        task_bpmn_ids = [
            step_id_to_bpmn_id[s.get("step_id", "")]
            for s in raw_steps
            if s.get("step_id", "") in step_id_to_bpmn_id
            and (s.get("element_type") or s.get("type", "")) not in (self._START_TYPES | self._END_TYPES)
        ]
        pos_index = {bid: i for i, bid in enumerate(task_bpmn_ids)}

        orphan_sources = [bid for bid in task_bpmn_ids if bid not in has_outgoing]
        orphan_sinks = [bid for bid in task_bpmn_ids if bid not in has_incoming]
        auto_connected = []
        for src in list(orphan_sources):
            src_pos = pos_index[src]
            best_tgt = None
            for tgt in orphan_sinks:
                if pos_index[tgt] > src_pos and (src, tgt) not in explicit_pairs:
                    if (tgt, src) in explicit_pairs:
                        continue
                    best_tgt = tgt
                    break
            if best_tgt:
                fc += 1
                sequence_flows.append({"id": f"Flow_{fc:02d}", "source_ref": src,
                                        "target_ref": best_tgt, "_synthetic": True})
                auto_connected.append(f"{src}→{best_tgt}")
                explicit_pairs.add((src, best_tgt))
                has_outgoing.add(src)
                has_incoming.add(best_tgt)
                orphan_sinks.remove(best_tgt)
        if auto_connected:
            print(f"  WARN [{process_id}]: {len(auto_connected)} orphan node(s) auto-connected "
                  f"(review extraction data): {auto_connected}", file=sys.stderr)

        if task_bpmn_ids and start_id not in has_outgoing:
            fc += 1
            sequence_flows.insert(0, {"id": f"Flow_{fc:02d}", "source_ref": start_id,
                                       "target_ref": task_bpmn_ids[0]})
            has_incoming.add(task_bpmn_ids[0])

        if task_bpmn_ids and end_id not in has_incoming:
            true_sinks = [bid for bid in task_bpmn_ids if bid not in has_outgoing]
            if not true_sinks:
                true_sinks = [task_bpmn_ids[-1]]
            for sink in true_sinks:
                fc += 1
                sequence_flows.append({"id": f"Flow_{fc:02d}", "source_ref": sink,
                                        "target_ref": end_id})
                has_outgoing.add(sink)

        owners = [s.get("owner") for s in raw_steps if s.get("owner") and "automated" not in (s.get("owner") or "").lower()]
        primary_owner = max(set(owners), key=owners.count) if owners else "Unknown"
        confidences = [_normalize_confidence(s.get("confidence", "MEDIUM")) for s in raw_steps if s.get("confidence")]
        conf_counts = {c: confidences.count(c) for c in set(confidences)}
        confidence = max(conf_counts, key=conf_counts.get) if conf_counts else "MEDIUM"

        return {
            "stage": stage, "name": sp["name"], "process_id": process_id,
            "description": f"{len(raw_steps)} steps across {len(lanes)} {'role' if any(l['type'] == 'role' for l in lanes) else 'system'}{'s' if len(lanes) != 1 else ''}",
            "version": "1.0", "confidence": confidence, "owner": primary_owner,
            "called_from": [], "calls": [], "lanes": lanes, "steps": bpmn_steps,
            "sequence_flows": sequence_flows,
            "pain_count": sum(1 for s in raw_steps if "pain" in (s.get("annotations") or [])),
            "opp_count": sum(1 for s in raw_steps if any(a in (s.get("annotations") or []) for a in ("optimisation", "automation"))),
        }

    def _build_lanes(self, steps):
        seen = {}
        for step in steps:
            lane_name = step.get("lane_id")
            if lane_name and lane_name.lower() not in seen:
                seen[lane_name.lower()] = lane_name
        if not seen:
            seen["manual"] = "Manual"
        result = []
        for i, (_, n) in enumerate(seen.items()):
            if _is_tool_name(n):
                icon = _get_tool_icon(n)
                logo_url, emoji = icon["url"], icon["emoji"]
            else:
                logo_url, emoji = None, None
            result.append({"id": sanitize_lane_id(n), "name": n, "type": classify_lane(n), "order": i, "logo_url": logo_url, "emoji": emoji})
        return result

    def _build_meeting_refs(self, step):
        refs = []
        for src in (step.get("sources") or []):
            if not isinstance(src, dict):
                continue
            if src.get("kind") == "fathom":
                session = self._find_session_by_number(src.get("session_id"))
                refs.append({
                    "speaker": src.get("speaker", ""),
                    "meeting_title": session.get("label", f"Session {src.get('session_id', '?')}"),
                    "meeting_date": session.get("date", ""),
                    "quote": src.get("quote", ""),
                    "meeting_id": session.get("fathom_meeting_id", ""),
                    "timestamp_seconds": src.get("timestamp_seconds", 0),
                    "fathom_url": session.get("fathom_url", ""),
                })
        if not refs and step.get("meeting_references"):
            for mr in step["meeting_references"]:
                mid = mr.get("meeting_id") or mr.get("fathom_meeting_id", "")
                session = self._find_session(mid)
                refs.append({"speaker": mr.get("speaker") or step.get("source_speaker", ""), "meeting_title": session.get("label", "Meeting"), "meeting_date": session.get("date", ""), "quote": mr.get("transcript_excerpt") or mr.get("quote", ""), "meeting_id": mid, "timestamp_seconds": mr.get("timestamp_seconds", 0), "fathom_url": session.get("fathom_url", "")})
        return refs

    def _find_session(self, mid):
        for s in self.sessions:
            if str(s.get("fathom_meeting_id")) == str(mid):
                return s
        return {}

    def _find_session_by_number(self, num):
        if num is None:
            return {}
        for s in self.sessions:
            if s.get("session_number") == num:
                return s
        return {}


# ─── BPMN XML Generator (semantic only — no DI positioning) ──────────────

class BpmnXmlGenerator:
    """Generates semantic BPMN 2.0 XML without diagram interchange (DI) elements.

    Layout is added by ELK.js via layout_bpmn_xml(). This class only produces
    the process logic: tasks, gateways, lanes, and sequence flows.
    """

    def __init__(self, process_data):
        self.proc = process_data
        self.lanes = process_data["lanes"]
        self.steps = process_data["steps"]
        self.flows = process_data["sequence_flows"]

    def generate(self):
        pid = self.proc["process_id"].replace("-", "_")
        lines = ['<?xml version="1.0" encoding="UTF-8"?>']
        lines.append(
            '<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"'
            ' xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI"'
            ' xmlns:dc="http://www.omg.org/spec/DD/20100524/DC"'
            ' xmlns:di="http://www.omg.org/spec/DD/20100524/DI"'
            ' xmlns:bioc="http://bpmn.io/schema/bpmn/biocolor/1.0"'
            ' xmlns:color="http://www.omg.org/spec/BPMN/non-normative/color/1.0"'
            f' id="Definitions_{pid}" targetNamespace="http://bosar.agency/bpmn">'
        )
        lines.append(
            f'<bpmn:collaboration id="Collaboration_{pid}">'
            f'<bpmn:participant id="Participant_{pid}" name="{xml_escape(self.proc["name"])}" processRef="Process_{pid}" />'
            f'</bpmn:collaboration>'
        )
        lines.append(
            f'<bpmn:process id="Process_{pid}" name="{xml_escape(self.proc["name"])}" isExecutable="false">'
            f'<bpmn:laneSet id="LaneSet_1">'
        )
        for lane in self.lanes:
            refs = "".join(
                f'<bpmn:flowNodeRef>{s["bpmn_id"]}</bpmn:flowNodeRef>'
                for s in self.steps if s.get("lane_id") == lane["id"]
            )
            lines.append(f'<bpmn:lane id="{lane["id"]}" name="{xml_escape(lane["name"])}">{refs}</bpmn:lane>')
        lines.append('</bpmn:laneSet>')

        for step in self.steps:
            lines.append(self._element_xml(step))
        for flow in self.flows:
            na = f' name="{xml_escape(flow["condition_label"])}"' if flow.get("condition_label") else ""
            lines.append(f'<bpmn:sequenceFlow id="{flow["id"]}"{na} sourceRef="{flow["source_ref"]}" targetRef="{flow["target_ref"]}" />')
        for step in self.steps:
            df = step.get("data_flow")
            if not df or not isinstance(df, dict):
                continue
            mechanism = df.get("mechanism", "")
            if not mechanism or mechanism == "unknown":
                continue
            desc = df.get("description", "")
            text = f"{mechanism.replace('_', ' ').title()}: {desc}" if desc else mechanism.replace("_", " ").title()
            ann_id = f"Ann_{step['bpmn_id']}"
            assoc_id = f"Assoc_{step['bpmn_id']}"
            lines.append(f'<bpmn:textAnnotation id="{ann_id}"><bpmn:text>{xml_escape(text)}</bpmn:text></bpmn:textAnnotation>')
            lines.append(f'<bpmn:association id="{assoc_id}" sourceRef="{ann_id}" targetRef="{step["bpmn_id"]}" associationDirection="None" />')
        lines.append('</bpmn:process>')
        lines.append('</bpmn:definitions>')
        return "\n".join(lines)

    def _element_xml(self, step):
        bid = step["bpmn_id"]
        name = xml_escape(step["title"])
        inc = "".join(f'<bpmn:incoming>{f["id"]}</bpmn:incoming>' for f in self.flows if f["target_ref"] == bid)
        out = "".join(f'<bpmn:outgoing>{f["id"]}</bpmn:outgoing>' for f in self.flows if f["source_ref"] == bid)
        etype = step.get("type", "task")
        if etype in ("start", "start_event"):
            return f'<bpmn:startEvent id="{bid}" name="{name}">{out}</bpmn:startEvent>'
        if etype in ("end", "end_event"):
            return f'<bpmn:endEvent id="{bid}" name="{name}">{inc}</bpmn:endEvent>'
        if etype in ("intermediate_catch_event",):
            event_def = step.get("event_definition", "")
            inner = ""
            if event_def == "timer":
                inner = f'<bpmn:timerEventDefinition id="TimerDef_{bid}" />'
            elif event_def == "message":
                inner = f'<bpmn:messageEventDefinition id="MsgDef_{bid}" />'
            elif event_def == "error":
                inner = f'<bpmn:errorEventDefinition id="ErrDef_{bid}" />'
            elif event_def == "signal":
                inner = f'<bpmn:signalEventDefinition id="SigDef_{bid}" />'
            return f'<bpmn:intermediateCatchEvent id="{bid}" name="{name}">{inc}{out}{inner}</bpmn:intermediateCatchEvent>'
        if etype in ("intermediate_throw_event",):
            event_def = step.get("event_definition", "")
            inner = ""
            if event_def == "message":
                inner = f'<bpmn:messageEventDefinition id="MsgDef_{bid}" />'
            elif event_def == "signal":
                inner = f'<bpmn:signalEventDefinition id="SigDef_{bid}" />'
            return f'<bpmn:intermediateThrowEvent id="{bid}" name="{name}">{inc}{out}{inner}</bpmn:intermediateThrowEvent>'
        if etype in ("decision", "exclusive_gateway"):
            gw_dir = self._gateway_direction(bid)
            default_attr = self._default_flow_attr(step, bid)
            return f'<bpmn:exclusiveGateway id="{bid}" name="{name}" isMarkerVisible="true" gatewayDirection="{gw_dir}"{default_attr}>{inc}{out}</bpmn:exclusiveGateway>'
        if etype in ("parallel_fork", "parallel_join", "parallel_gateway"):
            gw_dir = self._gateway_direction(bid)
            return f'<bpmn:parallelGateway id="{bid}" name="{name}" gatewayDirection="{gw_dir}">{inc}{out}</bpmn:parallelGateway>'
        tags = {"user_task": "userTask", "service_task": "serviceTask", "send_task": "sendTask", "receive_task": "receiveTask", "manual_task": "manualTask"}
        tag = tags.get(step.get("task_type", "user_task"), "userTask")
        return f'<bpmn:{tag} id="{bid}" name="{name}">{inc}{out}</bpmn:{tag}>'

    def _gateway_direction(self, bid):
        inc_count = sum(1 for f in self.flows if f["target_ref"] == bid)
        out_count = sum(1 for f in self.flows if f["source_ref"] == bid)
        if inc_count <= 1 and out_count >= 2:
            return "Diverging"
        if inc_count >= 2 and out_count <= 1:
            return "Converging"
        if inc_count >= 2 and out_count >= 2:
            return "Mixed"
        return "Unspecified"

    def _default_flow_attr(self, step, bid):
        default_fid = step.get("default_flow_id")
        if not default_fid:
            return ""
        matching = [f["id"] for f in self.flows
                    if f["source_ref"] == bid and f.get("_source_flow_id") == default_fid]
        if matching:
            return f' default="{matching[0]}"'
        return ""


# ─── Bioc Colors ──────────────────────────────────────────────────────────


_BIOC_COLORS = {
    "pain": {"stroke": "#c62828", "fill": "#ffebee"},
    "automation": {"stroke": "#1565c0", "fill": "#e3f2fd"},
    "optimisation": {"stroke": "#2e7d32", "fill": "#e8f5e9"},
}

_BIOC_NS = "http://bpmn.io/schema/bpmn/biocolor/1.0"
_COLOR_NS = "http://www.omg.org/spec/BPMN/non-normative/color/1.0"


def inject_bioc_colors(xml_string: str, step_annotations: dict) -> str:
    """Add bioc:stroke/bioc:fill color attributes to BPMNShape elements.

    step_annotations maps bpmn_id -> list of annotation strings.
    Colors are persisted in the .bpmn file so they render in bpmn.io.
    """
    if not step_annotations:
        return xml_string

    NS = {
        "bpmndi": "http://www.omg.org/spec/BPMN/20100524/DI",
    }
    ET.register_namespace("bioc", _BIOC_NS)
    ET.register_namespace("color", _COLOR_NS)

    try:
        root = ET.fromstring(xml_string)
    except ET.ParseError:
        return xml_string

    for shape in root.iter(f'{{{NS["bpmndi"]}}}BPMNShape'):
        be = shape.get("bpmnElement", "")
        annotations = step_annotations.get(be, [])
        if not annotations:
            continue
        color = None
        for ann in annotations:
            ann_str = ann.get("value", "") if isinstance(ann, dict) else ann
            if ann_str in _BIOC_COLORS:
                color = _BIOC_COLORS[ann_str]
                break
        if color:
            shape.set(f'{{{_BIOC_NS}}}stroke', color["stroke"])
            shape.set(f'{{{_BIOC_NS}}}fill', color["fill"])
            shape.set(f'{{{_COLOR_NS}}}background-color', color["fill"])
            shape.set(f'{{{_COLOR_NS}}}border-color', color["stroke"])

    xml_out = ET.tostring(root, encoding="unicode", xml_declaration=False)
    return '<?xml version="1.0" encoding="UTF-8"?>\n' + xml_out


def layout_bpmn_xml(semantic_xml: str, proc: dict = None, step_annotations: dict = None) -> str:
    """Add DI positioning to semantic BPMN XML using bpmn-auto-layout-extended."""
    node_modules = AUTO_LAYOUT_SCRIPT.parent / "node_modules"
    if not AUTO_LAYOUT_SCRIPT.exists() or not node_modules.exists():
        print("  WARN: auto-layout unavailable (run npm install in bpmn-layout/)", file=sys.stderr)
        return semantic_xml

    in_path = out_path = None
    try:
        with tempfile.NamedTemporaryFile(mode='w', suffix='.bpmn', delete=False) as f_in:
            f_in.write(semantic_xml)
            in_path = f_in.name
        out_path = in_path + ".laid-out.bpmn"
        result = subprocess.run(
            ["node", str(AUTO_LAYOUT_SCRIPT), in_path, out_path],
            capture_output=True, text=True, timeout=30,
            cwd=str(AUTO_LAYOUT_SCRIPT.parent),
        )
        if result.returncode == 0:
            with open(out_path) as f:
                xml_out = f.read()
            return inject_bioc_colors(xml_out, step_annotations or {})
        print(f"  WARN: auto-layout failed: {result.stderr.strip()}", file=sys.stderr)
    except (subprocess.TimeoutExpired, FileNotFoundError, OSError) as e:
        print(f"  WARN: auto-layout error: {e}", file=sys.stderr)
    finally:
        for p in [in_path, out_path]:
            if p:
                try:
                    os.unlink(p)
                except OSError:
                    pass

    return _manual_layout_fallback(semantic_xml)


def _manual_layout_fallback(semantic_xml: str) -> str:
    """
    Generate a simple grid-based BPMNDiagram when bpmn-auto-layout-extended fails.
    Places elements left-to-right within each lane in flowNodeRef order.
    """
    # Element size constants
    TASK_W, TASK_H = 120, 80
    EVENT_W, EVENT_H = 36, 36
    GW_W, GW_H = 50, 50
    LANE_HEADER_W = 30         # width of the lane label strip on the left
    PARTICIPANT_HEADER_H = 30  # height of the participant label strip on top
    LANE_H = 160               # height per lane
    COL_STEP = 200             # horizontal spacing between element centres
    X_START = 80               # x of first element centre (from lane content left edge)

    ns = {
        'bpmn': 'http://www.omg.org/spec/BPMN/20100524/MODEL',
        'bpmndi': 'http://www.omg.org/spec/BPMN/20100524/DI',
        'dc': 'http://www.omg.org/spec/DD/20100524/DC',
        'di': 'http://www.omg.org/spec/DD/20100524/DI',
    }
    try:
        root = ET.fromstring(semantic_xml.split('\n', 1)[1] if semantic_xml.startswith('<?xml') else semantic_xml)
    except ET.ParseError:
        return semantic_xml

    bpmn_ns = 'http://www.omg.org/spec/BPMN/20100524/MODEL'

    # Find collaboration and process
    collab = root.find(f'{{{bpmn_ns}}}collaboration')
    process = root.find(f'{{{bpmn_ns}}}process')
    if process is None:
        return semantic_xml

    collab_id = collab.get('id') if collab is not None else 'Collab_1'
    participant = collab.find(f'{{{bpmn_ns}}}participant') if collab is not None else None
    participant_id = participant.get('id') if participant is not None else 'Participant_1'
    participant_name = participant.get('name', '') if participant is not None else ''

    # Build element-type lookup
    tag_to_type = {}
    for child in process:
        tag = child.tag.split('}')[-1] if '}' in child.tag else child.tag
        eid = child.get('id')
        if eid:
            tag_to_type[eid] = tag

    def element_size(eid):
        t = tag_to_type.get(eid, 'task')
        t_lower = t.lower()
        if 'event' in t_lower:
            return EVENT_W, EVENT_H
        if 'gateway' in t_lower:
            return GW_W, GW_H
        return TASK_W, TASK_H

    # Gather lanes in order
    lane_set = process.find(f'{{{bpmn_ns}}}laneSet')
    lanes = []
    if lane_set is not None:
        for lane in lane_set.findall(f'{{{bpmn_ns}}}lane'):
            ref_els = [r.text for r in lane.findall(f'{{{bpmn_ns}}}flowNodeRef') if r.text]
            lanes.append({'id': lane.get('id'), 'name': lane.get('name', ''), 'refs': ref_els})

    if not lanes:
        # Single implicit lane — all flow nodes
        refs = [child.get('id') for child in process
                if child.get('id') and 'Flow' not in child.tag and 'laneSet' not in child.tag]
        lanes = [{'id': 'Lane_1', 'name': '', 'refs': refs}]

    # Calculate max columns across lanes
    max_cols = max((len(l['refs']) for l in lanes), default=1)

    diagram_w = LANE_HEADER_W + X_START * 2 + (max_cols - 1) * COL_STEP + TASK_W
    diagram_h = PARTICIPANT_HEADER_H + len(lanes) * LANE_H

    # Build position map: eid -> (cx, cy) in diagram coordinates
    positions = {}
    for lane_idx, lane in enumerate(lanes):
        lane_y = PARTICIPANT_HEADER_H + lane_idx * LANE_H
        cy = lane_y + LANE_H // 2
        for col_idx, eid in enumerate(lane['refs']):
            cx = LANE_HEADER_W + X_START + col_idx * COL_STEP
            positions[eid] = (cx, cy)

    # Build DI XML string
    di_lines = []
    di_lines.append(
        f'  <bpmndi:BPMNDiagram id="BPMNDiagram_{collab_id}">'
    )
    di_lines.append(
        f'    <bpmndi:BPMNPlane id="BPMNPlane_{collab_id}" bpmnElement="{collab_id}">'
    )

    # Participant shape
    di_lines.append(
        f'      <bpmndi:BPMNShape id="{participant_id}_di" bpmnElement="{participant_id}" isHorizontal="true">'
        f'<dc:Bounds x="0" y="0" width="{diagram_w}" height="{diagram_h}" />'
        f'<bpmndi:BPMNLabel><dc:Bounds x="0" y="0" width="30" height="{diagram_h}" /></bpmndi:BPMNLabel>'
        f'</bpmndi:BPMNShape>'
    )

    # Lane shapes
    for lane_idx, lane in enumerate(lanes):
        lane_y = PARTICIPANT_HEADER_H + lane_idx * LANE_H
        lane_w = diagram_w - LANE_HEADER_W
        di_lines.append(
            f'      <bpmndi:BPMNShape id="{lane["id"]}_di" bpmnElement="{lane["id"]}" isHorizontal="true">'
            f'<dc:Bounds x="{LANE_HEADER_W}" y="{lane_y}" width="{lane_w}" height="{LANE_H}" />'
            f'<bpmndi:BPMNLabel />'
            f'</bpmndi:BPMNShape>'
        )

    # Flow node shapes
    for eid, (cx, cy) in positions.items():
        w, h = element_size(eid)
        x, y = cx - w // 2, cy - h // 2
        di_lines.append(
            f'      <bpmndi:BPMNShape id="{eid}_di" bpmnElement="{eid}">'
            f'<dc:Bounds x="{x}" y="{y}" width="{w}" height="{h}" />'
            f'</bpmndi:BPMNShape>'
        )

    # Sequence flow edges (simple mid-point waypoints)
    for child in process.findall(f'{{{bpmn_ns}}}sequenceFlow'):
        fid = child.get('id')
        src = child.get('sourceRef')
        tgt = child.get('targetRef')
        if src in positions and tgt in positions:
            sx, sy = positions[src]
            tx, ty = positions[tgt]
            sw, sh = element_size(src)
            tw, th = element_size(tgt)
            # Exit from right edge of source, enter left edge of target
            p1x, p1y = sx + sw // 2, sy
            p2x, p2y = tx - tw // 2, ty
            di_lines.append(
                f'      <bpmndi:BPMNEdge id="{fid}_di" bpmnElement="{fid}">'
                f'<di:waypoint x="{p1x}" y="{p1y}" />'
                f'<di:waypoint x="{p2x}" y="{p2y}" />'
                f'</bpmndi:BPMNEdge>'
            )

    di_lines.append('    </bpmndi:BPMNPlane>')
    di_lines.append('  </bpmndi:BPMNDiagram>')

    # Inject the BPMNDiagram before </bpmn:definitions>
    closing_tag = '</bpmn:definitions>'
    if closing_tag in semantic_xml:
        return semantic_xml.replace(closing_tag, '\n'.join(di_lines) + '\n' + closing_tag)

    # Fallback: append before end
    return semantic_xml.rstrip() + '\n' + '\n'.join(di_lines) + '\n</bpmn:definitions>'


# ─── Multi-plane layout for sub-process drill-down ────────────────────────────

def _run_auto_layout(xml: str) -> "str | None":
    """Run bpmn-auto-layout-extended on the given XML. Returns laid-out XML or None."""
    node_modules = AUTO_LAYOUT_SCRIPT.parent / "node_modules"
    if not AUTO_LAYOUT_SCRIPT.exists() or not node_modules.exists():
        return None
    in_path = out_path = None
    try:
        with tempfile.NamedTemporaryFile(mode='w', suffix='.bpmn', delete=False) as f:
            f.write(xml)
            in_path = f.name
        out_path = in_path + ".out.bpmn"
        result = subprocess.run(
            ["node", str(AUTO_LAYOUT_SCRIPT), in_path, out_path],
            capture_output=True, text=True, timeout=30,
            cwd=str(AUTO_LAYOUT_SCRIPT.parent),
        )
        if result.returncode == 0:
            with open(out_path) as f:
                return f.read()
        print(f"  WARN: auto-layout failed: {result.stderr.strip()[:200]}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"  WARN: auto-layout error: {e}", file=sys.stderr)
        return None
    finally:
        for p in [in_path, out_path]:
            if p:
                try:
                    os.unlink(p)
                except OSError:
                    pass


def _layout_parent_stub(stage_id: str, stage_name: str, procs: list) -> "str | None":
    """Layout a flat stub BPMN where each sub-process is a simple task."""
    pid = stage_id.replace("-", "_")
    sp_ids = [p["process_id"].replace("-", "_") for p in procs]
    n = len(procs)
    lines = ['<?xml version="1.0" encoding="UTF-8"?>']
    lines.append(
        f'<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"'
        f' xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI"'
        f' xmlns:dc="http://www.omg.org/spec/DD/20100524/DC"'
        f' xmlns:di="http://www.omg.org/spec/DD/20100524/DI"'
        f' id="Definitions_{pid}" targetNamespace="http://bosar.agency/bpmn">'
    )
    lines.append(
        f'<bpmn:collaboration id="Collab_{pid}">'
        f'<bpmn:participant id="Part_{pid}" name="{xml_escape(stage_name)}" processRef="Process_{pid}" />'
        f'</bpmn:collaboration>'
    )
    lines.append(f'<bpmn:process id="Process_{pid}" isExecutable="false">')
    start_id = f"PStart_{pid}"
    end_id = f"PEnd_{pid}"
    lines.append(f'<bpmn:startEvent id="{start_id}"><bpmn:outgoing>PFlow_0</bpmn:outgoing></bpmn:startEvent>')
    for i, (proc, sp_id) in enumerate(zip(procs, sp_ids)):
        lines.append(
            f'<bpmn:task id="{sp_id}" name="{xml_escape(proc["name"])}">'
            f'<bpmn:incoming>PFlow_{i}</bpmn:incoming>'
            f'<bpmn:outgoing>PFlow_{i + 1}</bpmn:outgoing>'
            f'</bpmn:task>'
        )
    lines.append(f'<bpmn:endEvent id="{end_id}"><bpmn:incoming>PFlow_{n}</bpmn:incoming></bpmn:endEvent>')
    for i, sp_id in enumerate(sp_ids):
        src = start_id if i == 0 else sp_ids[i - 1]
        lines.append(f'<bpmn:sequenceFlow id="PFlow_{i}" sourceRef="{src}" targetRef="{sp_id}" />')
    last = sp_ids[-1] if sp_ids else start_id
    lines.append(f'<bpmn:sequenceFlow id="PFlow_{n}" sourceRef="{last}" targetRef="{end_id}" />')
    lines.append('</bpmn:process>')
    lines.append('</bpmn:definitions>')
    return _run_auto_layout("\n".join(lines))


def _extract_bpmn_diagram(xml: str) -> "ET.Element | None":
    """Extract the first BPMNDiagram element from a laid-out BPMN."""
    try:
        root = ET.fromstring(xml)
        di_ns = "http://www.omg.org/spec/BPMN/20100524/DI"
        for diag in root.iter(f'{{{di_ns}}}BPMNDiagram'):
            return diag
    except ET.ParseError:
        pass
    return None


def _subprocess_content_xml(proc: dict) -> list:
    """Generate lane set, steps, and sequence flows for inside a <bpmn:subProcess>."""
    gen = BpmnXmlGenerator(proc)
    lanes = proc["lanes"]
    steps = proc["steps"]
    flows = proc["sequence_flows"]
    proc_id = proc["process_id"].replace("-", "_")
    lines = []
    lines.append(f'<bpmn:laneSet id="LS_{proc_id}">')
    for lane in lanes:
        refs = "".join(
            f'<bpmn:flowNodeRef>{s["bpmn_id"]}</bpmn:flowNodeRef>'
            for s in steps if s.get("lane_id") == lane["id"]
        )
        lines.append(f'<bpmn:lane id="{lane["id"]}" name="{xml_escape(lane["name"])}">{refs}</bpmn:lane>')
    lines.append('</bpmn:laneSet>')
    for step in steps:
        lines.append(gen._element_xml(step))
    for flow in flows:
        na = f' name="{xml_escape(flow["condition_label"])}"' if flow.get("condition_label") else ""
        lines.append(f'<bpmn:sequenceFlow id="{flow["id"]}"{na} sourceRef="{flow["source_ref"]}" targetRef="{flow["target_ref"]}" />')
    return lines


def _generate_semantic_multiplane(stage_id: str, stage_name: str, procs: list) -> str:
    """Generate semantic BPMN 2.0 XML with nested sub-process elements (no DI)."""
    pid = stage_id.replace("-", "_")
    n = len(procs)
    sp_ids = [p["process_id"].replace("-", "_") for p in procs]
    start_id = f"PStart_{pid}"
    end_id = f"PEnd_{pid}"
    lines = ['<?xml version="1.0" encoding="UTF-8"?>']
    lines.append(
        '<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL"'
        ' xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI"'
        ' xmlns:dc="http://www.omg.org/spec/DD/20100524/DC"'
        ' xmlns:di="http://www.omg.org/spec/DD/20100524/DI"'
        ' xmlns:bioc="http://bpmn.io/schema/bpmn/biocolor/1.0"'
        ' xmlns:color="http://www.omg.org/spec/BPMN/non-normative/color/1.0"'
        f' id="Definitions_{pid}" targetNamespace="http://bosar.agency/bpmn">'
    )
    lines.append(
        f'<bpmn:collaboration id="Collab_{pid}">'
        f'<bpmn:participant id="Part_{pid}" name="{xml_escape(stage_name)}" processRef="Process_{pid}" />'
        f'</bpmn:collaboration>'
    )
    lines.append(f'<bpmn:process id="Process_{pid}" isExecutable="false">')
    lines.append(f'<bpmn:startEvent id="{start_id}" name="Start"><bpmn:outgoing>PFlow_0</bpmn:outgoing></bpmn:startEvent>')
    for i, (proc, sp_id) in enumerate(zip(procs, sp_ids)):
        lines.append(f'<bpmn:subProcess id="{sp_id}" name="{xml_escape(proc["name"])}">')
        lines.append(f'<bpmn:incoming>PFlow_{i}</bpmn:incoming>')
        lines.append(f'<bpmn:outgoing>PFlow_{i + 1}</bpmn:outgoing>')
        lines.extend(_subprocess_content_xml(proc))
        lines.append('</bpmn:subProcess>')
    lines.append(f'<bpmn:endEvent id="{end_id}" name="End"><bpmn:incoming>PFlow_{n}</bpmn:incoming></bpmn:endEvent>')
    for i, sp_id in enumerate(sp_ids):
        src = start_id if i == 0 else sp_ids[i - 1]
        lines.append(f'<bpmn:sequenceFlow id="PFlow_{i}" sourceRef="{src}" targetRef="{sp_id}" />')
    last = sp_ids[-1] if sp_ids else start_id
    lines.append(f'<bpmn:sequenceFlow id="PFlow_{n}" sourceRef="{last}" targetRef="{end_id}" />')
    lines.append('</bpmn:process>')
    lines.append('</bpmn:definitions>')
    return "\n".join(lines)


def _stitch_multiplane(
    semantic_xml: str,
    parent_laid_out: "str | None",
    child_planes: list,
    step_annotations: dict,
) -> str:
    """Merge semantic XML with DI from parent + child layouts into one multi-plane BPMN."""
    di_ns = "http://www.omg.org/spec/BPMN/20100524/DI"
    bpmn_ns = "http://www.omg.org/spec/BPMN/20100524/MODEL"
    for ns, prefix in [
        (di_ns, "bpmndi"),
        ("http://www.omg.org/spec/DD/20100524/DC", "dc"),
        ("http://www.omg.org/spec/DD/20100524/DI", "di"),
        ("http://bpmn.io/schema/bpmn/biocolor/1.0", "bioc"),
        ("http://www.omg.org/spec/BPMN/non-normative/color/1.0", "color"),
        (bpmn_ns, "bpmn"),
    ]:
        ET.register_namespace(prefix, ns)

    try:
        root = ET.fromstring(semantic_xml)
    except ET.ParseError:
        return semantic_xml

    sp_id_set = {sp_id for sp_id, _ in child_planes}

    # Root BPMNDiagram from parent layout (sub-process shapes marked isExpanded=false)
    if parent_laid_out:
        parent_diag = _extract_bpmn_diagram(parent_laid_out)
        if parent_diag is not None:
            plane = parent_diag.find(f'{{{di_ns}}}BPMNPlane')
            if plane is not None:
                for shape in plane.findall(f'{{{di_ns}}}BPMNShape'):
                    if shape.get("bpmnElement", "") in sp_id_set:
                        shape.set("isExpanded", "false")
            root.append(parent_diag)

    # Child BPMNDiagrams — one per sub-process
    for sp_id, child_xml in child_planes:
        if not child_xml:
            continue
        child_diag = _extract_bpmn_diagram(child_xml)
        if child_diag is None:
            continue
        plane = child_diag.find(f'{{{di_ns}}}BPMNPlane')
        if plane is None:
            continue
        # Strip participant shapes (they reference the child stub's pool, not the sub-process)
        participant_ids: set = set()
        try:
            child_root = ET.fromstring(child_xml)
            for collab in child_root.iter(f'{{{bpmn_ns}}}collaboration'):
                for part in collab.iter(f'{{{bpmn_ns}}}participant'):
                    pid_val = part.get("id", "")
                    if pid_val:
                        participant_ids.add(pid_val)
        except ET.ParseError:
            pass
        for s in plane.findall(f'{{{di_ns}}}BPMNShape'):
            if s.get("bpmnElement", "") in participant_ids:
                plane.remove(s)
        plane.set("bpmnElement", sp_id)
        new_diag = ET.SubElement(root, f'{{{di_ns}}}BPMNDiagram')
        new_diag.set("id", f"Diagram_{sp_id}")
        new_diag.append(plane)

    xml_out = ET.tostring(root, encoding="unicode", xml_declaration=False)
    return inject_bioc_colors('<?xml version="1.0" encoding="UTF-8"?>\n' + xml_out, step_annotations)


def layout_bpmn_xml_multiplane(
    stage_id: str, stage_name: str, procs: list, step_annotations: dict
) -> str:
    """Multi-pass layout for BPMN collapsed sub-process drill-down.

    1. Layout parent stub (sub-processes as collapsed boxes via simple tasks)
    2. Layout each child sub-process independently as a flat BPMN
    3. Stitch parent DI + child DI into the semantic multi-plane XML
    """
    semantic_xml = _generate_semantic_multiplane(stage_id, stage_name, procs)

    node_modules = AUTO_LAYOUT_SCRIPT.parent / "node_modules"
    if not AUTO_LAYOUT_SCRIPT.exists() or not node_modules.exists():
        print("  WARN: auto-layout unavailable — multi-plane layout skipped", file=sys.stderr)
        return semantic_xml

    parent_xml = _layout_parent_stub(stage_id, stage_name, procs)

    child_planes: list = []
    for proc in procs:
        sp_id = proc["process_id"].replace("-", "_")
        child_semantic = BpmnXmlGenerator(proc).generate()
        child_laid_out = _run_auto_layout(child_semantic)
        child_planes.append((sp_id, child_laid_out))

    return _stitch_multiplane(semantic_xml, parent_xml, child_planes, step_annotations)


# ─── BPMN Validator ─────────────────────────────────────────────────────────

_BPMN_NS = {"bpmn": "http://www.omg.org/spec/BPMN/20100524/MODEL",
            "bpmndi": "http://www.omg.org/spec/BPMN/20100524/DI",
            "dc": "http://www.omg.org/spec/DD/20100524/DC",
            "di": "http://www.omg.org/spec/DD/20100524/DI"}

_TASK_TAGS = {"userTask", "serviceTask", "sendTask", "receiveTask",
              "manualTask", "scriptTask", "businessRuleTask", "task"}
_EVENT_TAGS = {"startEvent", "endEvent", "intermediateCatchEvent",
               "intermediateThrowEvent", "boundaryEvent"}
_GATEWAY_TAGS = {"exclusiveGateway", "parallelGateway",
                 "inclusiveGateway", "eventBasedGateway"}
_FLOW_NODE_TAGS = _TASK_TAGS | _EVENT_TAGS | _GATEWAY_TAGS | {"subProcess", "callActivity"}
_ARTIFACT_TAGS = {"textAnnotation", "association", "dataObjectReference", "group"}


class BpmnValidator:
    def __init__(self, xml_string: str, process_id: str):
        self.xml_string = xml_string
        self.pid = process_id
        self.errors: list[str] = []
        self.warnings: list[str] = []

    def validate(self) -> tuple[bool, list[str], list[str]]:
        try:
            self.root = ET.fromstring(self.xml_string)
        except ET.ParseError as e:
            self.errors.append(f"XML parse error: {e}")
            return False, self.errors, self.warnings

        self._collect_ids()
        self._check_id_uniqueness()
        self._check_sequence_flow_refs()
        self._check_start_end_events()
        self._check_gateway_flows()
        self._check_lane_flownode_refs()
        self._check_di_shape_coverage()
        self._check_di_edge_coverage()
        self._check_participant_process_ref()
        self._check_overlapping_shapes()
        return len(self.errors) == 0, self.errors, self.warnings

    def _collect_ids(self):
        self.all_ids: dict[str, int] = {}
        self.flow_node_ids: set[str] = set()
        self.seq_flow_ids: set[str] = set()
        self.process_ids: set[str] = set()

        for elem in self.root.iter():
            tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
            eid = elem.get("id")
            if eid:
                self.all_ids[eid] = self.all_ids.get(eid, 0) + 1
                if tag in _FLOW_NODE_TAGS:
                    self.flow_node_ids.add(eid)
                elif tag == "sequenceFlow":
                    self.seq_flow_ids.add(eid)
                elif tag == "process":
                    self.process_ids.add(eid)

    def _check_id_uniqueness(self):
        for eid, count in self.all_ids.items():
            if count > 1:
                self.errors.append(f"V03: Duplicate id '{eid}' appears {count} times")

    def _check_sequence_flow_refs(self):
        for elem in self.root.iter():
            tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
            if tag != "sequenceFlow":
                continue
            fid = elem.get("id", "?")
            src = elem.get("sourceRef")
            tgt = elem.get("targetRef")
            if src and src not in self.flow_node_ids:
                self.errors.append(f"V01: sequenceFlow '{fid}' sourceRef '{src}' not found")
            if tgt and tgt not in self.flow_node_ids:
                self.errors.append(f"V02: sequenceFlow '{fid}' targetRef '{tgt}' not found")

    def _check_start_end_events(self):
        for elem in self.root.iter():
            tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
            eid = elem.get("id", "?")
            if tag == "startEvent":
                inc = [c for c in elem if c.tag.split("}")[-1] == "incoming"]
                out = [c for c in elem if c.tag.split("}")[-1] == "outgoing"]
                if inc:
                    self.errors.append(f"V07: startEvent '{eid}' has {len(inc)} incoming flows")
                if not out:
                    self.warnings.append(f"V08: startEvent '{eid}' has no outgoing flows")
            elif tag == "endEvent":
                inc = [c for c in elem if c.tag.split("}")[-1] == "incoming"]
                out = [c for c in elem if c.tag.split("}")[-1] == "outgoing"]
                if out:
                    self.errors.append(f"V09: endEvent '{eid}' has {len(out)} outgoing flows")
                if not inc:
                    self.warnings.append(f"V10: endEvent '{eid}' has no incoming flows")

    def _check_gateway_flows(self):
        for elem in self.root.iter():
            tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
            if tag not in _GATEWAY_TAGS:
                continue
            eid = elem.get("id", "?")
            inc = [c for c in elem if c.tag.split("}")[-1] == "incoming"]
            out = [c for c in elem if c.tag.split("}")[-1] == "outgoing"]
            if not inc and not out:
                self.warnings.append(f"V15: gateway '{eid}' has no incoming or outgoing flows")
            elif not inc:
                self.warnings.append(f"V15: gateway '{eid}' has no incoming flows")
            elif not out:
                self.warnings.append(f"V15: gateway '{eid}' has no outgoing flows")

    def _check_lane_flownode_refs(self):
        for elem in self.root.iter():
            tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
            if tag != "flowNodeRef":
                continue
            ref = (elem.text or "").strip()
            if ref and ref not in self.flow_node_ids:
                self.errors.append(f"V05: flowNodeRef '{ref}' not found as a flow node")

    def _check_di_shape_coverage(self):
        shape_refs: set[str] = set()
        for elem in self.root.iter():
            tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
            if tag == "BPMNShape":
                be = elem.get("bpmnElement")
                if be:
                    shape_refs.add(be)
        for fid in self.flow_node_ids:
            if fid not in shape_refs:
                self.errors.append(f"V16: flow node '{fid}' has no BPMNShape")

    def _check_di_edge_coverage(self):
        edge_refs: set[str] = set()
        for elem in self.root.iter():
            tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
            if tag == "BPMNEdge":
                be = elem.get("bpmnElement")
                if be:
                    edge_refs.add(be)
                wps = [c for c in elem if c.tag.split("}")[-1] == "waypoint"]
                if len(wps) < 2:
                    self.errors.append(f"V18: BPMNEdge '{elem.get('id', '?')}' has {len(wps)} waypoints (min 2)")
        for sid in self.seq_flow_ids:
            if sid not in edge_refs:
                self.errors.append(f"V17: sequenceFlow '{sid}' has no BPMNEdge")

    def _check_participant_process_ref(self):
        for elem in self.root.iter():
            tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
            if tag != "participant":
                continue
            pid = elem.get("id", "?")
            pref = elem.get("processRef")
            if pref and pref not in self.process_ids:
                self.errors.append(f"V04: participant '{pid}' processRef '{pref}' not found")

    def _check_overlapping_shapes(self):
        positions: list[tuple[str, float, float]] = []
        for elem in self.root.iter():
            tag = elem.tag.split("}")[-1] if "}" in elem.tag else elem.tag
            if tag != "BPMNShape":
                continue
            be = elem.get("bpmnElement", "?")
            if be not in self.flow_node_ids:
                continue
            for child in elem:
                ctag = child.tag.split("}")[-1] if "}" in child.tag else child.tag
                if ctag == "Bounds":
                    x = float(child.get("x", 0))
                    y = float(child.get("y", 0))
                    positions.append((be, x, y))
        for i, (id_a, xa, ya) in enumerate(positions):
            for id_b, xb, yb in positions[i + 1:]:
                if abs(xa - xb) < 20 and abs(ya - yb) < 20:
                    self.errors.append(
                        f"V20: shapes '{id_a}' and '{id_b}' overlap at ({int(xa)},{int(ya)})"
                    )


# ─── HTML Generator ────────────────────────────────────────────────────────

class BpmnHtmlGenerator:
    def __init__(self, client_name, standalone_pain_points=None, standalone_optimisations=None):
        self.client_name = client_name
        # Maps stage key -> list of pain_point / optimisation dicts from findings.json
        self.standalone_pain_points = standalone_pain_points or {}
        self.standalone_optimisations = standalone_optimisations or {}

    def generate_process_page(self, proc, stage_label, bpmn_xml=""):
        bpmn_file = f"{proc['process_id']}.bpmn"
        performers = {}
        step_details = {}
        performer_colors = {}
        color_idx = [0]

        def get_color(owner):
            if not owner:
                return AUTO_COLOR
            if "automated" in owner.lower(): return AUTO_COLOR
            if owner not in performer_colors:
                performer_colors[owner] = PERFORMER_PALETTE[color_idx[0] % len(PERFORMER_PALETTE)]
                color_idx[0] += 1
            return performer_colors[owner]

        pain_ids = []
        auto_ids = []
        opp_ids = []
        pain_steps = []
        for step in proc["steps"]:
            etype = step.get("type", "task")
            if etype in ("start", "start_event", "end", "end_event", "decision", "exclusive_gateway"): continue
            bid = step["bpmn_id"]
            owner = step.get("owner") or "Unknown"
            annotations = step.get("annotations") or []
            performers[bid] = {"owner": owner, "initials": get_initials(owner), "hex": get_color(owner), "kind": "automation" if "automated" in owner.lower() else ("external" if classify_lane(owner) == "external" else "role")}
            detail_type = "pain" if "pain" in annotations else ("optimisation" if "optimisation" in annotations else ("automation" if "automation" in annotations else etype))
            tool_names = step.get("tool_names") or []
            detail = {"title": step["title"], "full_description": step.get("_full_description", step["title"]), "owner": owner, "type": detail_type, "tools": tool_names}
            if step.get("duration_per_instance_minutes"): detail["duration"] = f"{step['duration_per_instance_minutes']} min/instance"
            if step.get("time_estimate_hours_per_week"): detail["weekly"] = f"{step['time_estimate_hours_per_week']} hrs/week"
            if step.get("meeting_references"):
                mr = step["meeting_references"][0]
                if mr.get("quote"):
                    ts = mr.get("timestamp_seconds", 0)
                    furl = mr.get("fathom_url", "")
                    url = f"{furl}?t={ts}" if furl and ts else furl
                    detail["citation"] = {"speaker": mr.get("speaker", ""), "meeting": mr.get("meeting_title", ""), "quote": mr["quote"], "url": url}
            step_details[bid] = detail
            if "pain" in annotations:
                pain_steps.append({"title": step["title"], "desc": step.get("_full_description", step["title"]), "bid": bid})
                pain_ids.append(bid)
            if "automation" in annotations:
                auto_ids.append(bid)
            if "optimisation" in annotations:
                opp_ids.append(bid)

        lane_chips = "".join(_lane_chip(l) for l in proc["lanes"])
        step_count = sum(1 for s in proc["steps"] if s.get("type", "task") not in ("start", "start_event", "end", "end_event"))
        performers_json = json.dumps(performers)
        details_json = json.dumps(step_details)
        pain_ids_json = json.dumps(pain_ids)
        auto_ids_json = json.dumps(auto_ids)
        opp_ids_json = json.dumps(opp_ids)

        stage_key = proc.get("stage", "")
        standalone_pps = self.standalone_pain_points.get(stage_key, [])
        standalone_opps = self.standalone_optimisations.get(stage_key, [])

        pain_panel = ""
        if pain_steps or standalone_pps:
            pain_items = ""
            for p in pain_steps:
                has_more = p["desc"] and p["desc"] != p["title"]
                chevron = '<span class="pain-chevron">&#x25BE;</span>' if has_more else ''
                full_div = f'<div class="pain-full hidden">{_h(p["desc"])}</div>' if has_more else ''
                click = f' data-bid="{_h(p["bid"])}" onclick="togglePain(this)"' if has_more else ''
                pain_items += (
                    f'<div class="pain-row"{click}>'
                    f'<div class="pain-dot"></div>'
                    f'<div class="pain-body">'
                    f'<div class="pain-title">{_h(p["title"])}{chevron}</div>'
                    f'{full_div}'
                    f'</div></div>'
                )
            if pain_steps and standalone_pps:
                pain_items += '<div class="pain-divider"></div>'
            for pp in standalone_pps:
                title = pp.get("title", "")
                desc = pp.get("description", title)
                pain_items += (
                    f'<div class="pain-row standalone">'
                    f'<div class="pain-dot standalone"></div>'
                    f'<div class="pain-body">'
                    f'<div class="pain-title">{_h(title)}</div>'
                    f'<div class="pain-full">{_h(desc)}</div>'
                    f'</div></div>'
                )
            pain_panel = f'<div class="panel"><h3>Pain points</h3>{pain_items}</div>'

        opp_panel = ""
        if opp_ids or standalone_opps:
            opp_items = ""
            if standalone_opps:
                for op in standalone_opps:
                    title = op.get("title", "")
                    desc = op.get("description", title)
                    opp_items += (
                        f'<div class="pain-row standalone">'
                        f'<div class="pain-dot opp"></div>'
                        f'<div class="pain-body">'
                        f'<div class="pain-title">{_h(title)}</div>'
                        f'<div class="pain-full">{_h(desc)}</div>'
                        f'</div></div>'
                    )
            if opp_items:
                opp_panel = f'<div class="panel"><h3>Optimisations</h3>{opp_items}</div>'

        has_tool_lanes = any(l["type"] in ("system", "offline") for l in proc["lanes"])
        lane_section_title = "Tools (lanes)" if has_tool_lanes else "Roles (lanes)"

        def _legend_icon(lane):
            if lane["type"] == "role":
                return '<span class="legend-icon role">&#x1F464;</span>'
            if lane["type"] == "external":
                return '<span class="legend-icon external">&#x2197;</span>'
            em = lane.get("emoji") or DEFAULT_TOOL_EMOJI
            if lane.get("logo_url"):
                return (
                    f'<img class="legend-logo" src="{lane["logo_url"]}" alt="" '
                    f"onerror=\"this.outerHTML='<span class=legend-icon style=font-size:16px>{em}</span>'\">"
                )
            return f'<span class="legend-icon system" style="font-size:16px">{em}</span>'
        legend_lanes = "".join(
            f'<div class="legend-row">{_legend_icon(l)}<span>{_h(l["name"])}</span></div>'
            for l in proc["lanes"]
        )
        # Build tools legend from step tool_names (for role-based lane mode)
        legend_tools_html = ""
        if not has_tool_lanes:
            all_tools = set()
            for step in proc["steps"]:
                for tn in (step.get("tool_names") or []):
                    all_tools.add(tn)
            if all_tools:
                tool_items = ""
                for tn in sorted(all_tools):
                    icon = _get_tool_icon(tn)
                    em = icon["emoji"]
                    if icon["url"]:
                        tool_items += (
                            f'<div class="legend-row">'
                            f'<img class="legend-logo" src="{icon["url"]}" alt="" '
                            f"onerror=\"this.outerHTML='<span class=legend-icon style=font-size:16px>{em}</span>'\">"
                            f'<span>{_h(tn)}</span></div>'
                        )
                    else:
                        tool_items += f'<div class="legend-row"><span class="legend-icon system" style="font-size:16px">{em}</span><span>{_h(tn)}</span></div>'
                legend_tools_html = f'<div class="legend-section"><h4>Tools</h4>{tool_items}</div>'
        seen_owners = {}
        for step in proc["steps"]:
            if step["type"] in ("start", "end", "decision"):
                continue
            o = step.get("owner") or ""
            if o and o not in seen_owners:
                seen_owners[o] = 0
            if o:
                seen_owners[o] += 1
        legend_performers = ""
        for owner, count in seen_owners.items():
            is_auto = "automated" in owner.lower()
            color = get_color(owner)
            initials = "" if is_auto else get_initials(owner)
            auto_cls = " auto" if is_auto else ""
            legend_performers += f'<div class="legend-row"><span class="legend-chip{auto_cls}" style="background:{color}">{initials}</span><span>{_h(owner)}</span><span class="legend-meta">{count}</span></div>'
        legend_panel = f'<div class="panel"><h3>Legend</h3><div class="legend-section"><h4>{lane_section_title}</h4>{legend_lanes}</div>{legend_tools_html}<div class="legend-section"><h4>Performers</h4>{legend_performers}</div><div class="legend-section"><h4>Notation</h4><div class="notation-block"><span class="notation-pill pain">Pain point</span><span class="notation-pill opp">Optimisation</span><span class="notation-pill auto">Automated</span><span class="notation-pill decision">Decision</span></div></div></div>'

        page = '<!DOCTYPE html>\n<html lang="en"><head>\n'
        page += f'<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0">\n'
        page += f'<title>{_h(proc["name"])} - {_h(self.client_name)}</title>\n'
        page += '<link rel="stylesheet" href="../../assets/bpmn-viewer.css">\n'
        page += '<link rel="preconnect" href="https://fonts.googleapis.com">\n'
        page += '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n'
        page += '<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">\n'
        page += CSS_VIEWER + '\n</head><body>\n'
        page += f'<div class="topbar"><div class="topbar-left"><a href="../../1-client-website.html"><img src="{APG_LOGO_URL}" alt="APG" class="nav-logo"></a><div class="breadcrumb"><a href="../../1-client-website.html">Portal</a><span class="sep">/</span><a href="../../2-process-map.html">Landscape</a><span class="sep">/</span><a href="index.html">{_h(stage_label)}</a><span class="sep">/</span><span class="current">{_h(proc["name"])}</span></div></div>'
        page += f'<div class="topbar-actions"><span style="font-size:12px;color:var(--muted)">{_h(self.client_name)}</span><span class="version-pill">V1.0</span><button class="btn" onclick="downloadBpmn()">Download .bpmn</button></div></div>\n'
        page += f'<div class="title-strip"><h1>{_h(proc["name"])}</h1><div class="subtitle">{step_count} steps &middot; {proc["confidence"]} confidence</div><div class="lane-chips">{lane_chips}</div></div>\n'
        page += '<div class="main"><div class="canvas-wrap"><div id="canvas"></div>'
        page += '<div class="zoom-controls"><button class="zoom-btn" onclick="zoomIn()" title="Zoom in">+</button><button class="zoom-btn" onclick="zoomOut()" title="Zoom out">&minus;</button><button class="zoom-btn" onclick="zoomFit()" title="Fit">&#8634;</button></div>'
        page += '<div class="zoom-hint" id="zoom-hint">Scroll to zoom &middot; Drag to pan</div>'
        page += '<button class="legend-toggle" id="legend-toggle" onclick="toggleLegend()" title="BPMN legend">?</button>'
        page += ('<div class="bpmn-legend" id="bpmn-legend">'
                 '<div class="bpmn-legend-title">BPMN Notation</div>'
                 '<div class="bln-row"><svg viewBox="0 0 20 20" class="bln-icon"><circle cx="10" cy="10" r="8" fill="none" stroke="#22c55e" stroke-width="1.5"/></svg><span>Start</span></div>'
                 '<div class="bln-row"><svg viewBox="0 0 20 20" class="bln-icon"><circle cx="10" cy="10" r="8" fill="none" stroke="#c62828" stroke-width="3"/></svg><span>End</span></div>'
                 '<div class="bln-row"><svg viewBox="0 0 20 20" class="bln-icon"><rect x="1" y="4" width="18" height="12" rx="2" fill="none" stroke="#64748b" stroke-width="1.5"/></svg><span>Task</span></div>'
                 '<div class="bln-row"><svg viewBox="0 0 20 20" class="bln-icon"><polygon points="10,1 19,10 10,19 1,10" fill="none" stroke="#64748b" stroke-width="1.5"/><line x1="7" y1="10" x2="13" y2="10" stroke="#64748b" stroke-width="1.5"/></svg><span>Decision</span></div>'
                 '<div class="bln-row"><svg viewBox="0 0 20 20" class="bln-icon"><polygon points="10,1 19,10 10,19 1,10" fill="none" stroke="#64748b" stroke-width="1.5"/><line x1="10" y1="6" x2="10" y2="14" stroke="#64748b" stroke-width="1.5"/><line x1="6" y1="10" x2="14" y2="10" stroke="#64748b" stroke-width="1.5"/></svg><span>Parallel split/join</span></div>'
                 '<hr class="bln-sep">'
                 '<div class="bln-row"><svg viewBox="0 0 20 20" class="bln-icon"><rect x="1" y="4" width="18" height="12" rx="2" fill="#ffebee" stroke="#c62828" stroke-width="1.5"/></svg><span style="color:var(--pain)">Pain point</span></div>'
                 '<div class="bln-row"><svg viewBox="0 0 20 20" class="bln-icon"><rect x="1" y="4" width="18" height="12" rx="2" fill="#e3f2fd" stroke="#1565c0" stroke-width="1.5"/></svg><span style="color:var(--auto)">Automation opp.</span></div>'
                 '<div class="bln-row"><svg viewBox="0 0 20 20" class="bln-icon"><rect x="1" y="4" width="18" height="12" rx="2" fill="#e8f5e9" stroke="#2e7d32" stroke-width="1.5"/></svg><span style="color:var(--opp)">Optimisation opp.</span></div>'
                 '</div></div>\n')
        page += '<div class="sidebar">'
        page += f'<div class="panel"><h3>Process</h3><div class="field"><span class="label">Owner</span><span class="value">{_h(proc["owner"])}</span></div><div class="field"><span class="label">Steps</span><span class="value">{step_count}</span></div><div class="field"><span class="label">Confidence</span><span class="value">{proc["confidence"]}</span></div></div>'
        page += legend_panel
        page += pain_panel
        page += opp_panel
        page += '</div></div>\n'

        all_js_tools = set(k for k in TOOL_SIMPLE_ICON_SLUGS.keys())
        all_js_tools.update(k for k in TOOL_FAVICON_DOMAINS.keys())
        for d in step_details.values():
            for tn in (d.get("tools") or []):
                all_js_tools.add(tn)
        tool_icons_map = {}
        for tn in all_js_tools:
            icon = _get_tool_icon(tn)
            tool_icons_map[tn.lower()] = {"url": icon["url"], "emoji": icon["emoji"]}
        tool_icons_json = json.dumps(tool_icons_map)

        escaped_xml = bpmn_xml.replace('\\', '\\\\').replace('`', '\\`').replace('${', '\\${')
        page += '<script src="../../assets/bpmn-viewer.min.js"></script>\n'
        page += '<script>\n'
        page += "const bpmnViewer = new BpmnJS({ container: '#canvas' });\n"
        page += f"const bpmnXml = `{escaped_xml}`;\n"
        page += f"const performers = {performers_json};\n"
        page += f"const stepDetails = {details_json};\n"
        page += f"const painIds = {pain_ids_json};\n"
        page += f"const autoIds = {auto_ids_json};\n"
        page += f"const oppIds = {opp_ids_json};\n"
        page += "function zoomIn(){bpmnViewer.get('canvas').zoom(bpmnViewer.get('canvas').zoom()*1.25)}\n"
        page += "function zoomOut(){bpmnViewer.get('canvas').zoom(bpmnViewer.get('canvas').zoom()*0.8)}\n"
        page += "function zoomFit(){bpmnViewer.get('canvas').zoom('fit-viewport')}\n"
        page += f"function downloadBpmn(){{const b=new Blob([bpmnXml],{{type:'application/xml'}});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='{bpmn_file}';a.click()}}\n"
        page += "async function load(){await bpmnViewer.importXML(bpmnXml);zoomFit();applyMarkers();attachOverlays();setupClick();setTimeout(()=>{const h=document.getElementById('zoom-hint');if(h)h.style.opacity='0'},3000)}\n"
        page += "function applyMarkers(){const canvas=bpmnViewer.get('canvas');painIds.forEach(id=>{try{canvas.addMarker(id,'pain-node')}catch(e){}});autoIds.forEach(id=>{try{canvas.addMarker(id,'auto-node')}catch(e){}});oppIds.forEach(id=>{try{canvas.addMarker(id,'opp-node')}catch(e){}})}\n"
        page += "function attachOverlays(){const overlays=bpmnViewer.get('overlays');const ICONS=" + tool_icons_json + ";Object.entries(performers).forEach(([id,p])=>{const chip=document.createElement('div');chip.className='performer-chip'+(p.kind==='automation'?' auto':'');chip.style.background=p.hex;chip.title=p.owner;if(p.kind!=='automation'){chip.innerHTML='<span class=\"initials\">'+p.initials+'</span>'}try{const el2=bpmnViewer.get('elementRegistry').get(id);const chipLeft=el2?Math.max(0,Math.floor((el2.width-20)/2)):22;overlays.add(id,'perf',{position:{top:2,left:Math.max(el2.width-24,0)},html:chip})}catch(e){}});Object.entries(stepDetails).forEach(([id,d])=>{if(d.type==='pain'){const el=bpmnViewer.get('elementRegistry').get(id);const w=el?el.width:120;const pill=document.createElement('div');pill.className='pain-indicator';pill.textContent='Pain';try{overlays.add(id,'pain',{position:{top:-12,left:w-50},html:pill})}catch(e){}}if(d.tools&&d.tools.length){const el=bpmnViewer.get('elementRegistry').get(id);const wrap=document.createElement('div');wrap.className='tool-overlay';d.tools.forEach(t=>{const key=t.toLowerCase();const icon=ICONS[key];const em=(icon&&icon.emoji)||'\\uD83D\\uDD27';if(icon&&icon.url){const img=document.createElement('img');img.src=icon.url;img.alt=t;img.title=t;img.className='tool-icon';img.onerror=function(){const sp=document.createElement('span');sp.className='tool-emoji';sp.textContent=em;sp.title=t;this.parentNode.replaceChild(sp,this)};wrap.appendChild(img)}else{const sp=document.createElement('span');sp.className='tool-emoji';sp.textContent=em;sp.title=t;wrap.appendChild(sp)}});if(wrap.children.length)try{overlays.add(id,'tools',{position:{top:el.height-20,left:8},html:wrap})}catch(e){}}})}\n"
        page += "function setupClick(){bpmnViewer.get('eventBus').on('element.click',function(e){const d=stepDetails[e.element.id];if(!d)return;document.getElementById('modal-title').textContent=d.title;let html='<div class=\"detail-desc\">'+esc(d.full_description)+'</div><div class=\"detail-meta\">';if(d.type==='pain')html+='<span class=\"badge pain\">Pain point</span>';if(d.type==='optimisation')html+='<span class=\"badge opp\">Optimisation</span>';if(d.type==='automation')html+='<span class=\"badge auto\">Automated</span>';html+='<span>'+esc(d.owner)+'</span>';if(d.duration)html+=' &middot; <span>'+esc(d.duration)+'</span>';if(d.weekly)html+=' &middot; <span>'+esc(d.weekly)+'</span>';html+='</div>';if(d.tools&&d.tools.length){html+='<div class=\"detail-meta\" style=\"margin-top:2px\">Tools: '+d.tools.map(esc).join(', ')+'</div>'}if(d.citation){html+='<div class=\"detail-cite\"><div class=\"quote\">'+esc(d.citation.quote)+'</div><div class=\"cite-meta\">'+esc(d.citation.speaker)+' &middot; '+esc(d.citation.meeting)+'</div>';if(d.citation.url)html+='<a class=\"fathom-link\" href=\"'+d.citation.url+'\" target=\"_blank\">Open in Fathom &rarr;</a>';html+='</div>'}document.getElementById('modal-body').innerHTML=html;document.getElementById('step-modal').classList.add('visible');document.getElementById('step-modal-overlay').classList.add('visible')})}\n"
        page += "function closeModal(){document.getElementById('step-modal').classList.remove('visible');document.getElementById('step-modal-overlay').classList.remove('visible')}\n"
        page += "function toggleLegend(){const l=document.getElementById('bpmn-legend');const b=document.getElementById('legend-toggle');l.classList.toggle('visible');b.classList.toggle('active')}\n"
        page += "function esc(s){return(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}\n"
        page += "function togglePain(row){row.classList.toggle('open');var f=row.querySelector('.pain-full');if(f)f.classList.toggle('hidden');var bid=row.dataset.bid;if(bid){var c=bpmnViewer.get('canvas');try{if(row.classList.contains('open')){c.addMarker(bid,'pain-selected');var el=bpmnViewer.get('elementRegistry').get(bid);if(el)c.scrollToElement(el)}else{c.removeMarker(bid,'pain-selected')}}catch(e){}}}\n"
        page += "document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});\n"
        page += "load().catch(e=>{document.getElementById('canvas').innerHTML='<p style=\"padding:40px;color:red;\">Failed to render BPMN: '+e.message+'</p>'});\n"
        page += '</script>\n'
        page += '<div class="step-modal-overlay" id="step-modal-overlay" onclick="closeModal()"></div>\n'
        page += '<div class="step-modal" id="step-modal"><div class="step-modal-head"><h3 id="modal-title">Step details</h3><button class="step-modal-close" onclick="closeModal()">&#215;</button></div><div id="modal-body" class="step-modal-body"></div></div>\n'
        page += '</body></html>'
        return page

    def generate_grouped_stage_page(self, stage_data: dict, bpmn_xml: str) -> str:
        """Viewer HTML for a grouped stage with BPMN collapsed sub-process drill-down."""
        label = stage_data["label"]
        stage_slug = slugify(stage_data["stage"])
        bpmn_file = f"{stage_slug}.bpmn"
        procs = stage_data["processes"]

        # Merge performers / step_details / annotation IDs from all sub-processes
        performers: dict = {}
        step_details: dict = {}
        pain_ids: list = []
        auto_ids: list = []
        opp_ids: list = []
        pain_steps: list = []
        performer_colors: dict = {}
        color_idx = [0]

        def get_color(owner):
            if not owner:
                return AUTO_COLOR
            if "automated" in owner.lower():
                return AUTO_COLOR
            if owner not in performer_colors:
                performer_colors[owner] = PERFORMER_PALETTE[color_idx[0] % len(PERFORMER_PALETTE)]
                color_idx[0] += 1
            return performer_colors[owner]

        for proc in procs:
            for step in proc["steps"]:
                etype = step.get("type", "task")
                if etype in ("start", "start_event", "end", "end_event", "decision", "exclusive_gateway"):
                    continue
                bid = step["bpmn_id"]
                owner = step.get("owner") or "Unknown"
                annotations = step.get("annotations") or []
                performers[bid] = {
                    "owner": owner, "initials": get_initials(owner),
                    "hex": get_color(owner),
                    "kind": "automation" if "automated" in owner.lower() else (
                        "external" if classify_lane(owner) == "external" else "role"
                    ),
                }
                detail_type = (
                    "pain" if "pain" in annotations else
                    "optimisation" if "optimisation" in annotations else
                    "automation" if "automation" in annotations else etype
                )
                tool_names = step.get("tool_names") or []
                detail: dict = {
                    "title": step["title"],
                    "full_description": step.get("_full_description", step["title"]),
                    "owner": owner, "type": detail_type, "tools": tool_names,
                }
                if step.get("duration_per_instance_minutes"):
                    detail["duration"] = f"{step['duration_per_instance_minutes']} min/instance"
                if step.get("time_estimate_hours_per_week"):
                    detail["weekly"] = f"{step['time_estimate_hours_per_week']} hrs/week"
                if step.get("meeting_references"):
                    mr = step["meeting_references"][0]
                    if mr.get("quote"):
                        ts = mr.get("timestamp_seconds", 0)
                        furl = mr.get("fathom_url", "")
                        url = f"{furl}?t={ts}" if furl and ts else furl
                        detail["citation"] = {
                            "speaker": mr.get("speaker", ""),
                            "meeting": mr.get("meeting_title", ""),
                            "quote": mr["quote"], "url": url,
                        }
                step_details[bid] = detail
                if "pain" in annotations:
                    pain_steps.append({"title": step["title"], "desc": step.get("_full_description", step["title"]), "bid": bid})
                    pain_ids.append(bid)
                if "automation" in annotations:
                    auto_ids.append(bid)
                if "optimisation" in annotations:
                    opp_ids.append(bid)

        total_steps = sum(
            sum(1 for s in p["steps"] if s.get("type", "task") not in ("start", "start_event", "end", "end_event"))
            for p in procs
        )
        total_pain = sum(p.get("pain_count", 0) for p in procs)

        # Sub-process overview sidebar panel
        sp_items = ""
        for p in procs:
            sc = sum(1 for s in p["steps"] if s.get("type", "task") not in ("start", "start_event", "end", "end_event"))
            pc = p.get("pain_count", 0)
            pain_badge = f'<span class="badge pain" style="font-size:10px;padding:1px 6px">{pc} pain</span>' if pc else ""
            sp_items += f'<div class="field"><span class="label" style="font-size:11px">{_h(p["name"])}</span><span class="value" style="font-size:11px">{sc} steps {pain_badge}</span></div>'
        sp_panel = f'<div class="panel"><h3>Sub-processes</h3>{sp_items}</div>'

        # Pain panel
        stage_key = stage_data.get("stage", "")
        standalone_pps = self.standalone_pain_points.get(stage_key, [])
        standalone_opps = self.standalone_optimisations.get(stage_key, [])

        pain_panel = ""
        if pain_steps or standalone_pps:
            pain_items = ""
            for p in pain_steps:
                has_more = p["desc"] and p["desc"] != p["title"]
                chevron = '<span class="pain-chevron">&#x25BE;</span>' if has_more else ''
                full_div = f'<div class="pain-full hidden">{_h(p["desc"])}</div>' if has_more else ''
                click = f' data-bid="{_h(p["bid"])}" onclick="togglePain(this)"' if has_more else ''
                pain_items += (
                    f'<div class="pain-row"{click}>'
                    f'<div class="pain-dot"></div>'
                    f'<div class="pain-body"><div class="pain-title">{_h(p["title"])}{chevron}</div>{full_div}</div></div>'
                )
            if pain_steps and standalone_pps:
                pain_items += '<div class="pain-divider"></div>'
            for pp in standalone_pps:
                title = pp.get("title", "")
                desc = pp.get("description", title)
                pain_items += (
                    f'<div class="pain-row standalone">'
                    f'<div class="pain-dot standalone"></div>'
                    f'<div class="pain-body">'
                    f'<div class="pain-title">{_h(title)}</div>'
                    f'<div class="pain-full">{_h(desc)}</div>'
                    f'</div></div>'
                )
            pain_panel = f'<div class="panel"><h3>Pain points</h3>{pain_items}</div>'

        opp_panel = ""
        if standalone_opps:
            opp_items = ""
            for op in standalone_opps:
                title = op.get("title", "")
                desc = op.get("description", title)
                opp_items += (
                    f'<div class="pain-row standalone">'
                    f'<div class="pain-dot opp"></div>'
                    f'<div class="pain-body">'
                    f'<div class="pain-title">{_h(title)}</div>'
                    f'<div class="pain-full">{_h(desc)}</div>'
                    f'</div></div>'
                )
            opp_panel = f'<div class="panel"><h3>Optimisations</h3>{opp_items}</div>'

        all_js_tools: set = set(k for k in TOOL_SIMPLE_ICON_SLUGS.keys())
        all_js_tools.update(k for k in TOOL_FAVICON_DOMAINS.keys())
        for d in step_details.values():
            for tn in (d.get("tools") or []):
                all_js_tools.add(tn)
        tool_icons_map = {tn.lower(): {"url": _get_tool_icon(tn)["url"], "emoji": _get_tool_icon(tn)["emoji"]} for tn in all_js_tools}
        tool_icons_json = json.dumps(tool_icons_map)

        performers_json = json.dumps(performers)
        details_json = json.dumps(step_details)
        pain_ids_json = json.dumps(pain_ids)
        auto_ids_json = json.dumps(auto_ids)
        opp_ids_json = json.dumps(opp_ids)
        escaped_xml = bpmn_xml.replace('\\', '\\\\').replace('`', '\\`').replace('${', '\\${')

        page = '<!DOCTYPE html>\n<html lang="en"><head>\n'
        page += f'<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0">\n'
        page += f'<title>{_h(label)} - {_h(self.client_name)}</title>\n'
        page += '<link rel="stylesheet" href="../../assets/bpmn-viewer.css">\n'
        page += '<link rel="preconnect" href="https://fonts.googleapis.com">\n'
        page += '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n'
        page += '<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">\n'
        # Extra CSS for bpmn-js breadcrumbs and custom drilldown button
        page += '<style>.bjs-breadcrumbs{font-family:Inter,sans-serif;font-size:12px;color:#64748b;padding:4px 8px;background:rgba(255,255,255,.9);border-radius:4px;margin:8px}.bjs-breadcrumbs .bjs-breadcrumbs-entry{color:#4a90a4;cursor:pointer}.bjs-breadcrumbs .bjs-breadcrumbs-entry:hover{text-decoration:underline}.bjs-drilldown{display:none!important}.sp-drilldown{width:20px;height:20px;background:#4a90a4;color:#fff;border:none;border-radius:4px;cursor:pointer;font-size:15px;font-weight:700;line-height:19px;text-align:center;opacity:.85;display:block}.sp-drilldown:hover{opacity:1;background:#3a7a8e}</style>\n'
        page += CSS_VIEWER + '\n</head><body>\n'
        page += f'<div class="topbar"><div class="topbar-left"><a href="../../1-client-website.html"><img src="{APG_LOGO_URL}" alt="APG" class="nav-logo"></a><div class="breadcrumb"><a href="../../1-client-website.html">Portal</a><span class="sep">/</span><a href="../../2-process-map.html">Landscape</a><span class="sep">/</span><span class="current">{_h(label)}</span></div></div>'
        page += f'<div class="topbar-actions"><span style="font-size:12px;color:var(--muted)">{_h(self.client_name)}</span><button class="btn" onclick="downloadBpmn()">Download .bpmn</button></div></div>\n'
        page += f'<div class="title-strip"><h1>{_h(label)}</h1><div class="subtitle">{len(procs)} sub-processes &middot; {total_steps} steps &middot; {total_pain} pain points &middot; <em>Click [+] on a sub-process to drill in</em></div></div>\n'
        page += '<div class="main"><div class="canvas-wrap"><div id="canvas"></div>'
        page += '<div class="zoom-controls"><button class="zoom-btn" onclick="zoomIn()" title="Zoom in">+</button><button class="zoom-btn" onclick="zoomOut()" title="Zoom out">&minus;</button><button class="zoom-btn" onclick="zoomFit()" title="Fit">&#8634;</button></div>'
        page += '<div class="zoom-hint" id="zoom-hint">Click [+] on a box to drill in &middot; Use breadcrumbs to go back</div>'
        page += '</div>'
        page += '<div class="sidebar">'
        page += f'<div class="panel"><h3>Stage</h3><div class="field"><span class="label">Processes</span><span class="value">{len(procs)}</span></div><div class="field"><span class="label">Steps</span><span class="value">{total_steps}</span></div><div class="field"><span class="label">Pain points</span><span class="value">{total_pain}</span></div></div>'
        page += sp_panel
        page += pain_panel
        page += opp_panel
        page += '</div></div>\n'
        page += '<script src="../../assets/bpmn-viewer.min.js"></script>\n'
        page += '<script>\n'
        page += "const bpmnViewer = new BpmnJS({ container: '#canvas' });\n"
        page += f"const bpmnXml = `{escaped_xml}`;\n"
        page += f"const performers = {performers_json};\n"
        page += f"const stepDetails = {details_json};\n"
        page += f"const painIds = {pain_ids_json};\n"
        page += f"const autoIds = {auto_ids_json};\n"
        page += f"const oppIds = {opp_ids_json};\n"
        page += "function zoomIn(){bpmnViewer.get('canvas').zoom(bpmnViewer.get('canvas').zoom()*1.25)}\n"
        page += "function zoomOut(){bpmnViewer.get('canvas').zoom(bpmnViewer.get('canvas').zoom()*0.8)}\n"
        page += "function zoomFit(){bpmnViewer.get('canvas').zoom('fit-viewport')}\n"
        page += f"function downloadBpmn(){{const b=new Blob([bpmnXml],{{type:'application/xml'}});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='{bpmn_file}';a.click()}}\n"
        page += "function applyMarkers(){const canvas=bpmnViewer.get('canvas');painIds.forEach(id=>{try{canvas.addMarker(id,'pain-node')}catch(e){}});autoIds.forEach(id=>{try{canvas.addMarker(id,'auto-node')}catch(e){}});oppIds.forEach(id=>{try{canvas.addMarker(id,'opp-node')}catch(e){}})}\n"
        page += "function attachOverlays(){const overlays=bpmnViewer.get('overlays');const ICONS=" + tool_icons_json + ";Object.entries(performers).forEach(([id,p])=>{const chip=document.createElement('div');chip.className='performer-chip'+(p.kind==='automation'?' auto':'');chip.style.background=p.hex;chip.title=p.owner;if(p.kind!=='automation'){chip.innerHTML='<span class=\"initials\">'+p.initials+'</span>'}try{const el2=bpmnViewer.get('elementRegistry').get(id);if(!el2)return;const chipLeft=Math.max(0,Math.floor((el2.width-20)/2));overlays.add(id,'perf',{position:{top:2,left:Math.max(el2.width-24,0)},html:chip})}catch(e){}});Object.entries(stepDetails).forEach(([id,d])=>{if(d.type==='pain'){const el=bpmnViewer.get('elementRegistry').get(id);if(!el)return;const w=el.width;const pill=document.createElement('div');pill.className='pain-indicator';pill.textContent='Pain';try{overlays.add(id,'pain',{position:{top:-12,left:w-50},html:pill})}catch(e){}}if(d.tools&&d.tools.length){const el=bpmnViewer.get('elementRegistry').get(id);if(!el)return;const wrap=document.createElement('div');wrap.className='tool-overlay';d.tools.forEach(t=>{const key=t.toLowerCase();const icon=ICONS[key];const em=(icon&&icon.emoji)||'\\uD83D\\uDD27';if(icon&&icon.url){const img=document.createElement('img');img.src=icon.url;img.alt=t;img.title=t;img.className='tool-icon';img.onerror=function(){const sp=document.createElement('span');sp.className='tool-emoji';sp.textContent=em;sp.title=t;this.parentNode.replaceChild(sp,this)};wrap.appendChild(img)}else{const sp=document.createElement('span');sp.className='tool-emoji';sp.textContent=em;sp.title=t;wrap.appendChild(sp)}});if(wrap.children.length)try{overlays.add(id,'tools',{position:{top:el.height-20,left:8},html:wrap})}catch(e){}}})}\n"
        page += "function setupDrilldown(){var er=bpmnViewer.get('elementRegistry');var overlays=bpmnViewer.get('overlays');var canvas=bpmnViewer.get('canvas');try{overlays.remove({type:'drilldown'})}catch(e){}er.forEach(function(el){if(el.type==='bpmn:SubProcess'&&el.collapsed){var btn=document.createElement('div');btn.className='sp-drilldown';btn.textContent='+';btn.title='Drill into '+(el.businessObject&&el.businessObject.name||'subprocess');btn.onclick=function(evt){evt.stopPropagation();var root=canvas.findRoot(el.id+'_plane');if(root)canvas.setRootElement(root)};try{overlays.add(el.id,'drilldown',{position:{bottom:2,left:Math.floor(el.width/2)-10},html:btn})}catch(e){}}})}\n"
        page += "function setupClick(){bpmnViewer.get('eventBus').on('element.click',function(e){if(e.element.type==='bpmn:SubProcess'&&e.element.collapsed){var root=bpmnViewer.get('canvas').findRoot(e.element.id+'_plane');if(root){bpmnViewer.get('canvas').setRootElement(root);return;}}const d=stepDetails[e.element.id];if(!d)return;document.getElementById('modal-title').textContent=d.title;let html='<div class=\"detail-desc\">'+esc(d.full_description)+'</div><div class=\"detail-meta\">';if(d.type==='pain')html+='<span class=\"badge pain\">Pain point</span>';if(d.type==='optimisation')html+='<span class=\"badge opp\">Optimisation</span>';if(d.type==='automation')html+='<span class=\"badge auto\">Automated</span>';html+='<span>'+esc(d.owner)+'</span>';if(d.duration)html+=' &middot; <span>'+esc(d.duration)+'</span>';if(d.weekly)html+=' &middot; <span>'+esc(d.weekly)+'</span>';html+='</div>';if(d.tools&&d.tools.length){html+='<div class=\"detail-meta\" style=\"margin-top:2px\">Tools: '+d.tools.map(esc).join(', ')+'</div>'}if(d.citation){html+='<div class=\"detail-cite\"><div class=\"quote\">'+esc(d.citation.quote)+'</div><div class=\"cite-meta\">'+esc(d.citation.speaker)+' &middot; '+esc(d.citation.meeting)+'</div>';if(d.citation.url)html+='<a class=\"fathom-link\" href=\"'+d.citation.url+'\" target=\"_blank\">Open in Fathom &rarr;</a>';html+='</div>'}document.getElementById('modal-body').innerHTML=html;document.getElementById('step-modal').classList.add('visible');document.getElementById('step-modal-overlay').classList.add('visible')})}\n"
        page += "function closeModal(){document.getElementById('step-modal').classList.remove('visible');document.getElementById('step-modal-overlay').classList.remove('visible')}\n"
        page += "function esc(s){return(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}\n"
        page += "function togglePain(row){row.classList.toggle('open');var f=row.querySelector('.pain-full');if(f)f.classList.toggle('hidden');var bid=row.dataset.bid;if(bid){var c=bpmnViewer.get('canvas');try{if(row.classList.contains('open')){c.addMarker(bid,'pain-selected');var el=bpmnViewer.get('elementRegistry').get(bid);if(el)c.scrollToElement(el)}else{c.removeMarker(bid,'pain-selected')}}catch(e){}}}\n"
        page += "async function load(){await bpmnViewer.importXML(bpmnXml);bpmnViewer.get('eventBus').on('root.set',function(){applyMarkers();attachOverlays();setupDrilldown();});zoomFit();applyMarkers();attachOverlays();setupDrilldown();setupClick();setTimeout(()=>{const h=document.getElementById('zoom-hint');if(h)h.style.opacity='0'},5000)}\n"
        page += "document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});\n"
        page += "load().catch(e=>{document.getElementById('canvas').innerHTML='<p style=\"padding:40px;color:red;\">Failed to render BPMN: '+e.message+'</p>'});\n"
        page += '</script>\n'
        page += '<div class="step-modal-overlay" id="step-modal-overlay" onclick="closeModal()"></div>\n'
        page += '<div class="step-modal" id="step-modal"><div class="step-modal-head"><h3 id="modal-title">Step details</h3><button class="step-modal-close" onclick="closeModal()">&#215;</button></div><div id="modal-body" class="step-modal-body"></div></div>\n'
        page += '</body></html>'
        return page

    def generate_stage_index(self, stage_data, grouped_href: str = ""):
        label = stage_data["label"]
        processes = stage_data["processes"]
        total_steps = sum(sum(1 for s in p["steps"] if s["type"] not in ("start","end")) for p in processes)
        total_pain = sum(p.get("pain_count", 0) for p in processes)

        if grouped_href:
            # Grouped stage: single card linking directly to the drill-down viewer
            total_all = sum(sum(1 for s in p["steps"] if s["type"] not in ("start", "end")) for p in processes)
            pain_flag = f'<span class="pain-flag">{total_pain} pain</span>' if total_pain else ""
            cards = f'<a class="card" href="{grouped_href}"><h3>{_h(label)}</h3><div class="card-sub">{len(processes)} sub-processes &middot; {total_all} steps &middot; Click [+] to drill into each group</div><div class="card-foot">{pain_flag}<span class="confidence medium">View</span></div></a>\n'
        else:
            cards = ""
            for p in processes:
                sc = sum(1 for s in p["steps"] if s["type"] not in ("start", "end"))
                pain_flag = f'<span class="pain-flag">{p["pain_count"]} pain</span>' if p.get("pain_count") else ""
                lane_chips = "".join(_lane_chip(l) for l in p["lanes"][:4])
                cards += f'<a class="card" href="{p["process_id"]}.html"><h3>{_h(p["name"])}</h3><div class="card-sub">{_h(p["description"])}</div><div class="lane-chips">{lane_chips}</div><div class="card-foot">{pain_flag}<span class="confidence {p["confidence"].lower()}">{p["confidence"]}</span></div></a>\n'

        return f'''<!DOCTYPE html>
<html lang="en"><head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>{_h(label)} - {_h(self.client_name)}</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
{CSS_LANDSCAPE}
</head><body>
<div class="topbar"><div class="topbar-left"><a href="../../1-client-website.html"><img src="{APG_LOGO_URL}" alt="APG" class="nav-logo"></a><div class="breadcrumb"><a href="../../1-client-website.html">Portal</a><span class="sep">/</span><a href="../../2-process-map.html">Landscape</a><span class="sep">/</span><span class="current">{_h(label)}</span></div></div><span style="font-size:12px;color:var(--muted)">{_h(self.client_name)}</span></div>
<div class="header"><h1>{_h(label)}</h1><div class="subtitle">{len(processes)} process{"es" if len(processes)!=1 else ""} &middot; {total_steps} steps &middot; {total_pain} pain points</div></div>
<div class="stages"><div class="card-grid">{cards}</div></div>
</body></html>'''

    def generate_landscape(self, all_stages):
        total_procs = sum(len(s["processes"]) for s in all_stages)
        total_steps = sum(sum(sum(1 for st in p["steps"] if st["type"] not in ("start","end")) for p in s["processes"]) for s in all_stages)
        total_pain = sum(sum(p.get("pain_count",0) for p in s["processes"]) for s in all_stages)
        total_opp = sum(sum(p.get("opp_count",0) for p in s["processes"]) for s in all_stages)

        cards = ""
        for i, sd in enumerate(all_stages):
            stage_slug = slugify(sd["stage"])
            pc = len(sd["processes"])
            sc = sum(sum(1 for s in p["steps"] if s["type"] not in ("start","end")) for p in sd["processes"])
            pain = sum(p.get("pain_count",0) for p in sd["processes"])
            pf = f'<span class="pain-flag">{pain} pain</span>' if pain else ""
            cards += f'<a class="card" href="processes/{stage_slug}/index.html"><div class="card-icon">&#9636;</div><h3>{_h(sd["label"])}</h3><div class="card-sub">{pc} process{"es" if pc!=1 else ""} &middot; {sc} steps</div><div class="card-foot">{pf}</div></a>\n'

        return f'''<!DOCTYPE html>
<html lang="en"><head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>Process Landscape - {_h(self.client_name)}</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
{CSS_LANDSCAPE}
</head><body>
<div class="topbar"><div class="topbar-left"><a href="1-client-website.html"><img src="{APG_LOGO_URL}" alt="APG" class="nav-logo"></a><div class="breadcrumb"><a href="1-client-website.html">Portal</a><span class="sep">/</span><span class="current">Process Landscape</span></div></div><div style="display:flex;align-items:center;gap:12px"><span style="font-size:12px;color:var(--muted)">{_h(self.client_name)}</span><span class="version-pill">V1.0 &middot; CURRENT STATE</span></div></div>
<div class="header"><h1>Process Landscape</h1><div class="subtitle">Click any stage to explore its processes.</div>
<div class="quick-stats"><div class="stat"><div class="num">{len(all_stages)}</div><div class="label">Stages</div></div><div class="stat"><div class="num">{total_procs}</div><div class="label">Processes</div></div><div class="stat"><div class="num">{total_steps}</div><div class="label">Steps</div></div><div class="stat"><div class="num pain">{total_pain}</div><div class="label">Pain points</div></div><div class="stat"><div class="num opp">{total_opp}</div><div class="label">Opportunities</div></div></div></div>
<div class="stages"><div class="card-grid">{cards}</div></div>
</body></html>'''


