# ─── Main ──────────────────────────────────────────────────────────────────

def main():
    parser = argparse.ArgumentParser(description="Generate BPMN process maps")
    parser.add_argument("--client-slug", required=True)
    parser.add_argument("--clients-dir", default=None)
    args = parser.parse_args()

    clients_dir = Path(args.clients_dir) if args.clients_dir else DRIVE_BASE
    client_dir = clients_dir / args.client_slug
    audit_dir = client_dir / "audit"

    extraction_path = audit_dir / "extraction.json"
    audit_data_path = audit_dir / "audit-data.json"

    if extraction_path.exists():
        print(f"Reading {extraction_path} (v4)")
        with open(extraction_path) as f:
            extraction = json.load(f)
        meta_path = audit_dir / "meta.json"
        client_name = args.client_slug.replace("-", " ").title()
        if meta_path.exists():
            with open(meta_path) as f:
                meta = json.load(f)
            client_name = meta.get("client", {}).get("business_name") or meta.get("business_name") or client_name
    elif audit_data_path.exists():
        print(f"Reading {audit_data_path} (v2/v3)")
        with open(audit_data_path) as f:
            data = json.load(f)
        extraction = data
        client_name = data.get("company_name") or args.client_slug.replace("-", " ").title()
    else:
        print(f"ERROR: No audit data found in {audit_dir}", file=sys.stderr)
        sys.exit(1)

    result = generate_bpmn_deliverables(extraction, client_name, client_dir / "deliverables")
    print(f"\nDone! Serve: cd \"{client_dir / 'deliverables'}\" && python -m http.server 8080")


def generate_bpmn_deliverables(ssad: dict, client_name: str, deliverables_dir: Path) -> str:
    """Generate BPMN 3-level hierarchy. Returns landscape HTML string.

    Writes processes/{stage}/{id}.bpmn + .html files as side effects.
    Called by generate.py --output process-map and by standalone main().
    """
    tools_lookup = {}
    for tool in ssad.get("tools", []):
        tid = tool.get("tool_id") or tool.get("id", "")
        tname = tool.get("tool_name") or tool.get("name", tid)
        tools_lookup[tid] = tname

    sessions = ssad.get("sessions", [])

    transformer = BpmnTransformer(ssad, tools_lookup, sessions)
    result = transformer.transform_all()
    all_stages = result["stages"]
    total_procs = sum(len(s["processes"]) for s in all_stages)
    print(f"BPMN: {client_name} — {total_procs} sub-processes across {len(all_stages)} stages")

    deliverables_dir.mkdir(parents=True, exist_ok=True)

    assets_dir = deliverables_dir / "assets"
    assets_dir.mkdir(exist_ok=True)
    _here = Path(__file__).parent / "bpmn-layout"
    shutil.copy2(_here / "bpmn-viewer.min.js", assets_dir / "bpmn-viewer.min.js")
    shutil.copy2(_here / "bpmn-viewer.css", assets_dir / "bpmn-viewer.css")

    old_pm = deliverables_dir / "2-process-map.html"
    if old_pm.exists():
        legacy = deliverables_dir / "process-map-legacy.html"
        if not legacy.exists():
            shutil.copy2(old_pm, legacy)
            print("  Backed up old process-map.html -> process-map-legacy.html")

    # Build stage-keyed lookups for standalone pain points and optimisations
    standalone_pain_by_stage: dict = {}
    for pp in ssad.get("pain_points", []):
        stage = pp.get("stage")
        if stage:
            standalone_pain_by_stage.setdefault(stage, []).append(pp)

    standalone_opp_by_stage: dict = {}
    for op in ssad.get("optimisations", []):
        stage = op.get("stage")
        if stage:
            standalone_opp_by_stage.setdefault(stage, []).append(op)

    html_gen = BpmnHtmlGenerator(
        client_name,
        standalone_pain_points=standalone_pain_by_stage,
        standalone_optimisations=standalone_opp_by_stage,
    )

    for stage_data in all_stages:
        stage_slug = slugify(stage_data["stage"])
        stage_dir = deliverables_dir / "processes" / stage_slug
        stage_dir.mkdir(parents=True, exist_ok=True)

        if stage_data.get("use_subprocess") and len(stage_data["processes"]) > 1:
            # Multi-plane drill-down: one BPMN file + one viewer for the whole stage
            procs = stage_data["processes"]
            all_annotations: dict = {}
            for p in procs:
                all_annotations.update({s["bpmn_id"]: s.get("annotations", []) for s in p["steps"]})

            print(f"  {stage_slug}/ — multi-plane layout ({len(procs)} sub-processes)...")
            bpmn_xml = layout_bpmn_xml_multiplane(
                stage_data["stage"], stage_data["label"], procs, all_annotations
            )

            validator = BpmnValidator(bpmn_xml, stage_slug)
            passed, v_errors, v_warnings = validator.validate()
            for w in v_warnings:
                print(f"    WARN: {w}")
            if not passed:
                print(f"  BPMN VALIDATION [{stage_slug}]: {len(v_errors)} error(s) — skipping output",
                      file=sys.stderr)
                for e in v_errors:
                    print(f"    ERROR: {e}", file=sys.stderr)
                (stage_dir / f"{stage_slug}.errors.json").write_text(json.dumps({
                    "process_id": stage_slug, "errors": v_errors, "warnings": v_warnings,
                }, indent=2))
            else:
                (stage_dir / f"{stage_slug}.bpmn").write_text(bpmn_xml)
                stage_html = html_gen.generate_grouped_stage_page(stage_data, bpmn_xml)
                (stage_dir / f"{stage_slug}.html").write_text(stage_html)
                (stage_dir / "index.html").write_text(
                    html_gen.generate_stage_index(stage_data, grouped_href=f"{stage_slug}.html")
                )
                print(f"  {stage_slug}/{stage_slug}.bpmn + .html (drill-down)")
        else:
            # Flat layout: one BPMN + HTML per process (existing behaviour)
            (stage_dir / "index.html").write_text(html_gen.generate_stage_index(stage_data))
            print(f"  {stage_slug}/index.html")

            for proc in stage_data["processes"]:
                semantic_xml = BpmnXmlGenerator(proc).generate()
                annotations_map = {s["bpmn_id"]: s.get("annotations", []) for s in proc["steps"]}
                bpmn_xml = layout_bpmn_xml(semantic_xml, proc=proc, step_annotations=annotations_map)

                validator = BpmnValidator(bpmn_xml, proc["process_id"])
                passed, v_errors, v_warnings = validator.validate()
                for w in v_warnings:
                    print(f"    WARN: {w}")
                if not passed:
                    print(f"  BPMN VALIDATION [{proc['process_id']}]: {len(v_errors)} error(s) — skipping output",
                          file=sys.stderr)
                    for e in v_errors:
                        print(f"    ERROR: {e}", file=sys.stderr)
                    (stage_dir / f"{proc['process_id']}.errors.json").write_text(json.dumps({
                        "process_id": proc["process_id"], "errors": v_errors, "warnings": v_warnings,
                    }, indent=2))
                    continue

                (stage_dir / f"{proc['process_id']}.bpmn").write_text(bpmn_xml)
                proc_html = html_gen.generate_process_page(proc, stage_data["label"], bpmn_xml)
                (stage_dir / f"{proc['process_id']}.html").write_text(proc_html)
                print(f"  {stage_slug}/{proc['process_id']}.bpmn + .html")

    landscape_html = html_gen.generate_landscape(all_stages)
    (deliverables_dir / "2-process-map.html").write_text(landscape_html)
    print("  2-process-map.html")

    return landscape_html


if __name__ == "__main__":
    main()
